INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('b00fc23b-bf61-4555-85ff-be44546f541f','Nike Mercurial Superfly 9 Elite','{"benefits":[{"header":"Brilliant Swoosh design","body":["Designed with the hard work of brilliance in mind, the textured Swoosh logo symbolises the friction that goes into polishing a gem before it shines. The Grey resembles the darkness you work under while the plate has an iridescent finish that represents your breakthrough moment when it''s time to shine."]},{"header":"Zoom, zoom","body":["The 3/4-length Air Zoom unit sits in the outsole and provides another level of springy underfoot feel that helps you move fast on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change direction quickly and confidently. Heel studs provide traction and stability when braking. Toe-off centre studs give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and a better fit in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium lining for optimal ball control at high speeds. The lining provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot. The pliability offers a more natural on-ball feel for shooting, dribbling or passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Not intended for use as personal protective equipment (PPE)","Cushioned insole","Colour Shown: Atmosphere Grey/Black","Style: FN5613-001","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/25cc3c76-9257-48f7-9908-2a9443c49e88/ZOOM+SUPERFLY+9+ELITE+FG+AS.png','488.41','2025-01-03 15:45:47.98694','2025-01-03 15:45:47.98694','football','men'),
	 ('32404178-cc77-4907-a8f5-c1da5962185d','Nike Superfly 10 Elite Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1385-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c961d409-51a5-42f1-a372-b7f860043645/ZM+SUPERFLY+10+ELITE+MDS+FG.png','574.62','2025-01-03 15:45:48.082773','2025-01-03 15:45:48.082773','football','men'),
	 ('51aea6b0-af02-41b1-8a3d-53a2088f7eda','Nike Vapor 16 Elite Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1392-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/451d1501-2758-4c49-bcd8-a7defcc5b5ab/ZOOM+VAPOR+16+ELITE+MDS+FG.png','530.20','2025-01-03 15:45:48.084255','2025-01-03 15:45:48.084255','football','men'),
	 ('8c27b0a5-cac1-4449-a6c8-9f6d2b6e9cbb','Nike Superfly 10 Elite Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1385-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c961d409-51a5-42f1-a372-b7f860043645/ZM+SUPERFLY+10+ELITE+MDS+FG.png','398.28','2025-01-03 15:45:48.156021','2025-01-03 15:45:48.156021','football','women'),
	 ('cb8172ac-75b8-49cd-8cf6-d46340cbff39','Nike Run Swift 3','{"benefits":[{"header":"Cushion with Every Step","body":["Foam cushioning delivers a soft underfoot feel. A higher foam height gives you a plush sensation with every step."]},{"header":"Secure Fit","body":["Flywire cables help secure your feet and provide support when you tighten the laces, so you can stay stable."]}],"product_details":[{"header":"Product Details","body":["Heel overlay for added security","Mesh by the toe for breathability","Flex grooves on rugged rubber outsole for flexibility","Colour Shown: Black/Anthracite/White/Metallic Gold","Style: DR2695-010","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b53e7394-ee2d-43b3-8579-1208f26c7d56/NIKE+RUN+SWIFT+3.png','752.13','2025-01-03 15:45:48.120504','2025-01-03 15:45:48.120504','running','men'),
	 ('412481b4-e658-45e4-b070-6c6aec1e9a68','Tatum 3 PF ''Zero Days Off''','{"benefits":[{"header":"Conforms to your moves","body":["A contouring fit offers stretch and containment. We studied players in action and layered materials in the upper where it mattered most. The result? Shoes designed to keep up with your game."]},{"header":"Lightest in flight","body":["Less weight means more speed, and we''re all about speed. A flexible textile upper helps Tatum''s latest signature shoe continue the line''s reign as the lightest performance shoes in our collection—now that''s champ talk."]},{"header":"Traction for quick cuts","body":["The Cushlon foam and a springy Air Zoom unit help provide a smooth ride underfoot. They work alongside a firm frame to help you feel secure whether you''re getting up or making quick cuts."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Seafoam/Spruce Aura/Arctic Orange/Apricot Agate","Style: FZ6601-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/03240aad-2e7f-43df-b129-65fefe67e8a6/JORDAN+TATUM+3+PF.png','803.15','2025-01-03 15:45:48.003697','2025-01-03 15:45:48.003697','basketball','men'),
	 ('f6499f08-18ba-424d-981c-40385d9c464b','Ja 2 ''Purple Sky'' EP','{"benefits":[{"header":"Purple Sky","body":["Watching Ja soar above the court is the same as staring at a purple night sky. Astral graphics and lavish lavender give this special design a Ja-sized lift-off."]},{"header":"Zoom, zoom","body":["A forefoot Air Zoom unit helps provide increased responsiveness and vertical acceleration."]},{"header":"Lighter design","body":["We removed as much material in the arch as possible without sacrificing support, which helps reduce the overall weight of the shoe. The midsole is made to mould to your foot for better containment and support when making quick, sudden movements."]},{"header":"Tractor-inspired traction","body":["The multi-directional traction pattern pays homage to the oversized tractor tyres Ja still trains on in the Morant family''s back garden."]},{"header":"Light and breathable","body":["Lightweight mesh offers comfort and breathability in the upper while engineered mesh on the big-toe side of the shoe gives you even more breathability."]}],"product_details":[{"header":"Product details","body":["Not intended for use as personal protective equipment (PPE)","Colour Shown: Bold Berry/Light Lemon Twist/Dark Raisin/Baltic Blue","Style: FD7327-500","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/20fd0937-0c1e-4149-b098-607ce9c428be/JA+2+EP.png','949.36','2025-01-03 15:45:48.000422','2025-01-03 15:45:48.000422','basketball','men'),
	 ('23934dd2-890f-4bac-a084-4c68a6723511','Luka 3 PF','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight comfort","body":["A moulded upper with medial cut-out helps provide lightweight comfort and structure without feeling too tight at the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Hyper Jade/Pink Prime/Hyper Grape","Style: FQ1285-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/754881e3-8550-4635-ab1a-99f0742be06d/JORDAN+LUKA+3+PF.png','396.16','2025-01-03 15:45:48.00138','2025-01-03 15:45:48.00138','basketball','men'),
	 ('3db39293-ca5e-4d71-aafd-b14d9489e183','LeBron XXII ''Tunnel Vision'' EP','{"benefits":[{"header":"Tunnel Vision","body":["Dark hues with bright accents create the look of a tunnel where LeBron locks in before taking the floor."]},{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["The synthetic leather upper offers lightweight containment with optimal breathability","Multi-directional traction pattern","Colour Shown: Black/Dark Grey/Field Purple/Laser Fuchsia","Style: FZ1095-001","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/882393e6-9ff2-4e8e-a2ce-91875992971c/LEBRON+XXII+EP.png','709.09','2025-01-03 15:45:48.005296','2025-01-03 15:45:48.005296','basketball','men'),
	 ('d451d606-f025-4f36-b34b-a79d0ebbae29','Luka 3 PF ''Photo Finish''','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight Comfort","body":["A seamless moulded upper with a medial cut-out helps provide lightweight comfort and structure without feeling too tight in the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: White/Volt Glow/Green Glow/Black","Style: HQ5055-107","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/04e752fb-1f6c-43c2-b617-6c076b2bca96/JORDAN+LUKA+3+PF.png','418.49','2025-01-03 15:45:48.006656','2025-01-03 15:45:48.006656','basketball','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('9231c822-df2d-464f-a289-3c928d9de868','Tatum 3 PF ''Sidewalk Chalk''','{"benefits":[{"header":"Conforms to your moves","body":["A contouring fit offers stretch and containment. We studied players in action and layered materials in the upper where it mattered most. The result? Shoes designed to keep up with your game."]},{"header":"Lightest in flight","body":["Less weight means more speed, and we''re all about speed. A flexible textile upper helps Tatum''s latest signature shoe continue the line''s reign as the lightest performance shoes in our collection—now that''s champ talk."]},{"header":"Traction for quick cuts","body":["The Cushlon foam and a springy Air Zoom unit help provide a smooth ride underfoot. They work alongside a firm frame to help you feel secure whether you''re getting up or making quick cuts."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Anthracite/Orange Pearl/Barely Green/Pale Ivory","Style: FZ6601-008","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/a7982b6c-0379-4234-9133-379454cafb5d/JORDAN+TATUM+3+PF.png','309.16','2025-01-03 15:45:48.00883','2025-01-03 15:45:48.00883','basketball','men'),
	 ('353afb0e-deb3-4d96-a6dd-e069e3ca2cbe','Luka 3 PF','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight comfort","body":["A seamless moulded upper with a medial cut-out helps provide lightweight comfort and structure without feeling too tight in the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: White/Grey Fog/Siren Red/Black","Style: FQ7455-106","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/cee1421c-5ced-4126-93e3-e73ac88c665e/JORDAN+LUKA+3+TB+PF.png','587.60','2025-01-03 15:45:48.009788','2025-01-03 15:45:48.009788','basketball','men'),
	 ('ee529eaf-d799-4652-958f-efe964b1ea36','Air Jordan XXXIX PF ''Croix''','{"benefits":[{"header":"All play with no crash","body":["We added a crash pad at the instep to help hold your foot in place and keep your toes from slamming into the toe box. After all, just because MJ lost a few toenails, it doesn''t mean you should have to."]},{"header":"Zoom into comfort","body":["ZoomX foam, Nike''s lightest high-efficiency foam, contours to the natural shape of your foot to give you soft and springy cushioning without weighing you down. We paired it with a full-length Air Zoom unit for snappy energy return."]},{"header":"Rock solid","body":["Remember MJ''s cross step? Of course you do. It influenced this shoe from the sole up. A built-in sidewall cupsole helps provide stability during lateral movements and allows for full engagement of the underfoot cushioning."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Black/Dark Powder Blue","Style: FQ0214-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/026c7567-2c54-405d-a605-d8b6b96f6093/AIR+JORDAN+XXXIX+PF.png','382.48','2025-01-03 15:45:48.014017','2025-01-03 15:45:48.014017','basketball','men'),
	 ('239e8cab-1fee-4cc6-9722-f7a286b4b4b5','Luka 3 PF','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight comfort","body":["A moulded upper with medial cut-out helps provide lightweight comfort and structure without feeling too tight at the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: White/Laser Orange/Gum Light Brown/Hyper Jade","Style: FQ1285-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/97740f01-a83d-41eb-877f-ba8ec50f090e/JORDAN+LUKA+3+PF.png','854.65','2025-01-03 15:45:48.014724','2025-01-03 15:45:48.014724','basketball','men'),
	 ('b8cd24dc-1c81-4a88-98fe-510c5d9ccb2f','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Football Grey/Pure Platinum/Plum Dust/Royal Pulse","Style: FN4322-004","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b5bea92b-2109-4c0f-86ad-7167cebd4477/NIKE+PRECISION+VII.png','304.13','2025-01-03 15:45:48.018029','2025-01-03 15:45:48.018029','basketball','men'),
