	 ('a097ab31-37a1-4ea6-8167-1f3fdd7bac46','LeBron Witness 8 EP','{"benefits":[{"header":"Max Air made","body":["A Max Air unit in the low-profile midsole is combined with a foam wrap-up for support when you''re moving in lateral directions. It helps cushion your landing while supporting the smooth transition from heel to toe. It also provides side-to-side stability and helps harness and direct your force."]},{"header":"Secure feel","body":["Breathable mesh provides a lightweight, conforming fit in the upper, from the webbing that harnesses your forefoot to the external moulded pieces that help secure your heel. Reinforced stitching along the sides helps the shoe fit snugly for full-foot containment."]},{"header":"Stick and Move","body":["We split the rubber outsole and partially cut it out under the arch to help it bend and flex while helping reduce its overall weight. A classic herringbone pattern adds durable traction."]}],"product_details":[{"header":"Product details","body":["Padded collar","Diamond-stitched quilted tongue","Colour Shown: Light Crimson/Bright Crimson/Gym Red/White","Style: FB2237-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf324a92-3ce0-47ac-be18-193f39f79095/LEBRON+WITNESS+VIII+EP.png','737.29','2025-01-03 15:45:48.047559','2025-01-03 15:45:48.047559','basketball','men'),
	 ('ee570ce4-493f-4582-b1a1-2c363d61b890','Nike Terrascout','{"benefits":[{"header":"Step into exploration","body":["Rubber outsole with rugged tread pattern helps provide durable traction. Flex grooves in the outsole add flexibility, helping every step feel natural."]},{"header":"Easy to pull on","body":["Lowered back collar works with pull tabs on the tongue and heel to help make these easy to pull on."]},{"header":"Warm and cosy details","body":["Quilted fabric around the collar pairs with a soft fleece lining to help keep your feet warm in cold weather."]}],"product_details":[{"header":"Product details","body":["Classic laces","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Sand Drift/Light British Tan/Seafoam/Baroque Brown","Style: HQ3472-122","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b2762ce4-fb6f-456a-b147-c05d150f0ae0/NIKE+TERRASCOUT+%28GS%29.png','752.07','2025-01-03 15:45:48.10446','2025-01-03 15:45:48.10446','lifestyle','men'),
	 ('d2dac9ff-82d5-4f0e-bb9a-e35d08d1f37c','Zion 3 ''Rising'' PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["A Nike Air unit helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Bleached Coral/Pale Ivory/Glacier Blue/Crimson Tint","Style: FZ1322-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/78da61b0-ba14-47b6-9e7f-7b21139b0bee/JORDAN+ZION+3+NRG+PF.png','734.66','2025-01-03 15:45:48.059341','2025-01-03 15:45:48.059341','basketball','men');
