	 ('c71c4eb8-ebaf-4eaa-b445-2b440c21aea7','Luka 3 PF ''Blurred Vision''','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight Comfort","body":["A seamless moulded upper with a medial cut-out helps provide lightweight comfort and structure without feeling too tight in the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Vapour Green/Cone/Psychic Purple/Hyper Jade","Style: HQ5048-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/3fe719ae-5373-4c19-b8c8-d68df6ce1976/JORDAN+LUKA+3+PF.png','437.99','2025-01-03 15:45:48.048214','2025-01-03 15:45:48.048214','basketball','men'),
	 ('d6784be1-9eaa-4ba3-a10d-c138a8458a36','Tatum 2 ''Legacy'' PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight Build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Black/Wolf Grey/Electric Green","Style: FJ6458-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/3bdf52f5-1615-4bdf-9936-355332055c21/JORDAN+TATUM+2+PF.png','751.66','2025-01-03 15:45:48.051436','2025-01-03 15:45:48.051436','basketball','men'),
	 ('1bde097c-2a9f-4dc8-becf-ba45889255d6','Zion 3 ''Orchid'' SE PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Herringbone traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Plum Fog/Sail/Black","Style: FN1778-500","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/18364584-e9cf-4d45-8b9c-b2349ca96401/JORDAN+ZION+3+SE+PF.png','796.35','2025-01-03 15:45:48.053621','2025-01-03 15:45:48.053621','basketball','men'),
	 ('2d3cab94-27b4-46b8-bb5f-4f3da19ab085','Luka 3 PF ''Blurred Vision''','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight Comfort","body":["A seamless moulded upper with a medial cut-out helps provide lightweight comfort and structure without feeling too tight in the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Vapour Green/Cone/Psychic Purple/Hyper Jade","Style: HQ5048-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/3fe719ae-5373-4c19-b8c8-d68df6ce1976/JORDAN+LUKA+3+PF.png','639.77','2025-01-03 15:45:48.055788','2025-01-03 15:45:48.055788','basketball','men'),
	 ('2b5d5d5b-e2f8-422c-85d2-864e67e4a7b4','Tatum 2 ''Vortex'' PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight Build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Mint Foam/Black/Hyper Jade/Lava Glow","Style: FJ6458-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d53a40e2-c781-416a-aa91-0434582290da/JORDAN+TATUM+2+PF.png','659.52','2025-01-03 15:45:48.057314','2025-01-03 15:45:48.057314','basketball','men'),
	 ('bf72dfbd-7381-4e4a-805c-de283b286462','Nike Phantom GX 2 Club','{"benefits":[{"header":"Grippy touch","body":["A grippy texture covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Reliable Traction","body":["The outsole plate has a broken-in feel to help you play fast from the first time you put these on."]},{"header":"Comfortable Fit","body":["Synthetic leather on the upper helps keep you comfortable on the pitch."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FJ2557-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a3ab8d17-8664-453b-8cfa-afa178155587/PHANTOM+GX+II+CLUB+FG%2FMG.png','685.37','2025-01-03 15:45:48.152327','2025-01-03 15:45:48.152327','football','women'),
	 ('15a27d5a-1f3b-4cad-8c57-dcaab72ced52','Zion 3 PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Off-White/Pink Foam/Vapour Green","Style: DR0676-103","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7bf745b8-5425-4051-8093-65cb8fa54fad/JORDAN+ZION+3+PF.png','480.18','2025-01-03 15:45:48.059989','2025-01-03 15:45:48.059989','basketball','men'),
	 ('8779b29c-494a-421c-8b7d-3fd4de565367','Nike Mercurial Superfly 10 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ1456-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/615bd8bf-ea41-487a-b3e1-70399eef6be6/ZM+SUPERFLY+10+ACAD+FG%2FMG.png','348.07','2025-01-03 15:45:48.064571','2025-01-03 15:45:48.064571','football','men'),
	 ('a507c3fc-aa0f-4882-a131-93bfd0382799','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Colour Shown: White/Blue Void/Metallic Silver/Bright Crimson","Style: FV2250-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e61080a2-fbe3-4bd9-917b-673bb10f6c73/AIR+MAX+DN+OLY.png','607.45','2025-01-03 15:45:48.097611','2025-01-03 15:45:48.097611','lifestyle','men'),
	 ('997373f9-4783-460c-b986-b9e9ec69311e','Nike Mercurial Superfly 10 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ1454-400","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f71f58eb-ad7b-4495-acd0-163411f79298/ZM+SUPERFLY+10+ELITE+FG.png','499.91','2025-01-03 15:45:48.068749','2025-01-03 15:45:48.068749','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('c13bbe65-f4c7-4c1e-80c6-cda28d1ecd11','Nike Mercurial Superfly 10 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["Rubber outsole provides traction on turf surfaces."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8331-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a10e080b-1985-48dc-83d5-ce0d86a294b7/ZM+SUPERFLY+10+ACADEMY+TF.png','595.22','2025-01-03 15:45:48.072599','2025-01-03 15:45:48.072599','football','men'),
	 ('064f6b35-a9e1-45a0-8686-492df0f5a3b6','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Tongue construction with additional padding gives you a secure feel and comfort in key strike zones. Microfibre lining creates a premium feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Soar/White","Style: DV4337-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d1afb0f2-6b34-43cf-92d0-f134dcafc3f7/LEGEND+10+ACADEMY+FG%2FMG.png','521.63','2025-01-03 15:45:48.075049','2025-01-03 15:45:48.075049','football','men'),
	 ('ba1cb302-20c3-452a-98bf-acd30ca35f26','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Even better, they don''t sacrifice the ball control you crave on the turf. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. Tongue construction with additional padding gives you a secure feel and comfort in key strike zones. Microfibre lining creates a premium feel."]},{"header":"Traction for the Turf","body":["A rubber outsole gives you traction on turf surfaces."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4342-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1c86329b-0136-4fb5-a7d3-cb1f0f7c5c7f/LEGEND+10+ACADEMY+TF.png','375.44','2025-01-03 15:45:48.076625','2025-01-03 15:45:48.076625','football','men'),
	 ('de267032-d9a5-4038-844e-6a1a534dd56a','Nike Tiempo Legend 10 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FQ3249-900","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c291f5b4-2622-4470-897e-0ecf77618bc6/LEGEND+10+ELITE+FG+OLY.png','760.36','2025-01-03 15:45:48.077371','2025-01-03 15:45:48.077371','football','men'),
	 ('60de3f77-2c9d-4dd6-8741-a165f91b0536','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: Barely Green/Jade Ice/Metallic Red Bronze/Vapour Green","Style: DD9304-301","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f8a23de7-3b97-40d4-910d-a8ed2099d0a0/NIKE+RENEW+ELEVATE+III.png','307.29','2025-01-03 15:45:47.996027','2025-01-03 15:45:47.996027','basketball','women'),
	 ('4193c8b7-182c-405a-8533-61df11a8f6d1','Nike Mercurial Vapor 16 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ1457-002","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/54449b69-7cc3-4459-b772-276fa932b9ee/ZM+VAPOR+16+ELITE+FG.png','668.83','2025-01-03 15:45:48.079637','2025-01-03 15:45:48.079637','football','men'),
	 ('02d727da-aaf8-4b19-bb2d-163c8acff075','Tatum 2 PF ''Red Cement''','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Bright Crimson/Black","Style: FJ6458-106","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/64e58613-39ba-4e9e-b9aa-0ba0cd15d847/JORDAN+TATUM+2+PF.png','593.34','2025-01-03 15:45:48.035426','2025-01-03 15:45:48.035426','basketball','men'),
	 ('139ff87f-eeea-4da7-80e3-21dbc91d4ae5','Nike Streakfly','{"benefits":[{"header":"Low and nimble","body":["A full-length ZoomX midsole provides optimal lightweight responsiveness. The foam stack heights are lower than the Vaporfly, saving weight and giving you a more aggressive feel. It results in a shoe so light it disappears on your foot, while still giving you the responsive cushioning of ZoomX foam, helping you reach your fastest pace throughout the turns and accelerations of any race."]},{"header":"Supportive and sleek","body":["An ultra-thin knit upper is light in weight while still providing the support you need for racing. Extra reinforcement in the forefoot helps keep you secure. The updated, sleek lacing system is laterally offset with a notched tongue to help relieve pressure on the top of the foot."]},{"header":"Grip where it counts","body":["Runner-informed data was used to create the outsole. It uses that information to place traction where you need it the most, with a pattern that connects to the pavement based on how your foot hits the ground. The result is solid grip from foot contact to toe-off, helping you stay ahead of the competition."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 185g (men''s size 9)","Heel-to-toe drop: 6mm","Colour Shown: Volt/Bright Crimson/Volt/Black","Style: DJ6566-700","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1bf6f4d9-0b4d-4477-9406-9f6c01250096/NIKE+ZOOMX+STREAKFLY.png','565.88','2025-01-03 15:45:48.117956','2025-01-03 15:45:48.117956','running','men'),
	 ('da6deac2-d8b7-48a5-a9bf-0c7dce389c40','Nike Mercurial Superfly 10 Elite SE','{"benefits":[{"header":"Behind the design","body":["This special design blends some of the Mercurial''s best moments in the women''s game over the years. And for the first time in the Merc''s history, we''ve applied a never-before-seen Chrome finish to the plate and upper. It shines a light on the on and off-pitch excellence of women athletes who have helped shape the boot''s high-speed history."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Hyper Turquoise/Black","Style: FQ8309-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9de0f8f0-3dd2-4e36-88d3-a2d79e4769f6/ZM+SUPERFLY+10+ELITE+SE+FG.png','378.24','2025-01-03 15:45:48.08107','2025-01-03 15:45:48.08107','football','men'),
	 ('13fa161e-700c-4d5f-9757-dec416ff1c41','Nike Superfly 10 Academy Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1380-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/acf1c7f9-bebd-41fc-b81f-9af24b7e2ddb/ZM+SUPERFLY+10+ACAD+MDS+FG%2FMG.png','609.25','2025-01-03 15:45:48.081966','2025-01-03 15:45:48.081966','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('21cde83e-24a8-4f57-b3fb-6a5823536dea','Nike Zoom Mercurial Superfly 9 Elite ''Marcus Rashford''','{"benefits":[{"header":"\"When you believe in yourself … \"","body":["\"Incredible things can happen.\" Check out the insole for an inspirational quote from Marcus. The graphics represent amplified sound waves, a nod to Marcus'' desire to lift up others, while the colours celebrate various debut boots he''s worn."]},{"header":"Springy underfoot feel","body":["The 3/4-length Zoom Air unit sits in the outsole and provides an additional level of springy underfoot cushioning that helps you move faster on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Drive your speed","body":["The speed cage inside the structure is made from a thin but strong material that secures the foot to the outsole without adding additional weight for optimal stability."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change directions quickly and confidently. Heel studs provide traction and stability when braking. Toe-off centre studs give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium material for optimal ball control at high speeds. The material provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot, giving you a more natural on-ball feel when dribbling, passing or scoring."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: White/Black","Style: FD1171-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8e644f9b-4db8-4d24-91d3-1edf45ae1e3c/ZOOM+SUPERFLY+9+ELITE+MR+FG.png','330.54','2025-01-03 15:45:48.086903','2025-01-03 15:45:48.086903','football','men'),
	 ('8d289c5d-c8a9-4492-bde3-e400daefa0e1','Nike TC 7900','{"benefits":[{"header":"Rugged and Tough","body":["Built to last, the upper features layers of synthetic materials that optimise durability. Webbing details and rubber accents on the heel add to the rugged look."]},{"header":"Comfort for Miles","body":["The thick foam cushioning adds unbelievable comfort while rubber accents on the sole add durability and traction."]}],"product_details":[{"header":"Product details","body":["Not intended for use as personal protective equipment (PPE)","Colour Shown: Sail/Black/Sail","Style: DD9682-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e3c24388-9a45-44e2-95c7-8f99d38bd882/W+NIKE+TC+7900.png','632.30','2025-01-03 15:45:47.996983','2025-01-03 15:45:47.996983','lifestyle','women'),
	 ('7c78c518-feea-4da0-a50f-4de5e12aa997','Nike Mercurial Superfly 10 Elite ''Kylian Mbappé''','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Light Laser Orange/Armoury Navy","Style: FQ8692-800","Country/Region of Origin: Bosnia \u0026 Herzegovina"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/737e6beb-15b3-4950-9c82-a642b67c1bfb/ZM+SUPERFLY+10+ELITE+KM+FG.png','304.04','2025-01-03 15:45:48.090184','2025-01-03 15:45:48.090184','football','men'),
	 ('1b217d02-84a8-4f24-92c9-0ef147724b1c','Nike Mercurial Vapor 16 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on longer, artificial-grass surfaces","Cushioned insole","Colour Shown: Volt/Black","Style: FQ8693-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/46957b3d-a518-4cb1-9ce1-b6d14e7c3016/ZM+VAPOR+16+ELITE+AG-PRO.png','507.51','2025-01-03 15:45:48.090943','2025-01-03 15:45:48.090943','football','men'),
	 ('ebe7f3cd-b60d-4735-947b-636746e6054b','Nike Superfly 9 Elite Mercurial Dream Speed','{"benefits":[{"header":"Springy underfoot feel","body":["The 3/4-length Air Zoom unit sits in the outsole and provides another level of springy underfoot feel that helps you move fast on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change directions quickly and confidently. Heel studs provide traction and stability when braking. Off-centre studs at the toe give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and better fit in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium lining for optimal ball control at high speeds. The lining provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot. The pliability offers a more natural on-ball feel for dribbling, passing or scoring."]},{"header":"Drive your speed","body":["The speed cage inside of the structure is made from a thin but strong material that secures the foot to the outsole without adding weight."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Green Strike/Stadium Green/Black","Style: FJ7186-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bb40352b-540b-4437-b32f-fa0525626bd6/ZOOM+SUPERFLY+9+MDS+ELITE+FG.png','819.01','2025-01-03 15:45:48.092441','2025-01-03 15:45:48.092441','football','men'),
	 ('0bf94313-97c3-4643-9863-f89720bade75','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Even better, they don''t sacrifice the ball control you crave on the court. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. The tongue construction with additional padding gives you a secure feel and comfort in key areas. Microfibre lining creates a premium feel."]},{"header":"Traction for the court","body":["The rubber outsole gives you traction for street, court and indoor surfaces."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Cushioned insole","Colour Shown: Pink Foam/Port Wine","Style: DV4341-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d135c2e6-fd7c-473d-8b2c-b45f31af088d/LEGEND+10+ACADEMY+IC.png','378.62','2025-01-03 15:45:48.094633','2025-01-03 15:45:48.094633','football','men'),
	 ('595021e9-4274-4264-b043-7c468af13dca','Nike Tiempo Legend 10 Club','{"benefits":[{"header":"Amplified touch","body":["The moulded synthetic leather mimics a quilted sensation for improved touch."]},{"header":"Natural, contouring fit","body":["The synthetic leather moulds to your foot and gives you better control, helping you stay comfortable for your match."]},{"header":"Traction for the Court","body":["The pattern on the outsole gives you traction for street, court and indoor surfaces."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Mesh tongue","Cushioned insole","Colour Shown: Soar/White","Style: DV4343-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8959d2c5-ea3a-4982-871f-bae185fa74cc/LEGEND+10+CLUB+IC.png','694.67','2025-01-03 15:45:47.997729','2025-01-03 15:45:47.997729','football','women'),
	 ('2396d8e7-fc93-4d89-b9e8-fb7dcc74d158','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Black/Metallic Dark Grey/Black","Style: DV3337-006","Country/Region of Origin: Indonesia, Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/35c07f69-1d7a-4272-abe4-4adf4b9a9d2f/AIR+MAX+DN.png','552.49','2025-01-03 15:45:48.099075','2025-01-03 15:45:48.099075','lifestyle','men'),
	 ('44d64962-33bf-4dce-9540-cc599bd08663','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: Black/Wolf Grey/Cool Grey/White","Style: DD9304-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/02908fb5-b54c-471f-b053-e3a6e306d7f4/NIKE+RENEW+ELEVATE+III.png','325.51','2025-01-03 15:45:47.999777','2025-01-03 15:45:47.999777','basketball','men'),
	 ('cf2f1803-f062-4f3d-baf9-619b96e521ca','Nike Alphafly 3 ''Eliud Kipchoge''','{"benefits":[{"header":"Keep growing","body":["Whenever someone trains with Eliud Kipchoge, they''re asked to plant a tree at his base camp to signify their growth. The sockliner graphics mimic that growth with branches moving forwards towards the front of the shoe. The Red Clay colour fade nods to the Kenyan dirt that stains the shoes when training. The font is a play on African trees that have fractal-like patterns on the surfaces."]},{"header":"Energy return for your marathon","body":["Two forefoot Air Zoom units combine with ZoomX foam to store and return the energy back to you, powering every step."]},{"header":"Propulsive feeling","body":["A full-length carbon-fibre plate delivers a propulsive sensation that helps you smoothly transition through every stride and tackle turns with confidence."]},{"header":"Cushioned ride","body":["Fully connected ZoomX foam creates an ultralight and cushioned feel, helping you stay fresh and comfortable from mile 1 to 26.2."]},{"header":"What''s new about the Alphafly 3?","body":["The Alphafly 3 is our lightest Alphafly ever, featuring a slightly wider carbon-fibre plate for increased stability, a fully connected ZoomX foam midsole for smoother transitions and an all-new AtomKnit upper designed for improved multi-directional containment and breathability."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 218g (Men''s size 9)","Heel-to-toe drop: 8mm","Colour Shown: Vapour Green/Dragon Red/Stadium Green/Black","Style: HJ7041-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9df887f6-b642-4788-9db0-8502f0be219f/AIR+ZOOM+ALPHAFLY+NEXT%25+3+EK.png','335.92','2025-01-03 15:45:48.108204','2025-01-03 15:45:48.108204','running','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('4c7c2f56-d6d0-4ff4-963a-a7dfe07af1fb','Nike Vaporfly 3','{"benefits":[{"header":"Fuel the fire","body":["This edition draws inspiration from the Japanese flag, ready to usher in the next centennial of this New Year''s relay race."]},{"header":"Fire underfoot","body":["A full-length carbon-fibre Flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ride","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft, yet supportive yarns deliver our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 200g (men''s size 9)","Heel-to-toe drop: 8mm","Wider toe area for a roomier fit","Internal foam pod on the heel for extra cushioning","Colour Shown: White/Black/University Red/Habanero Red","Style: HQ3504-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/97bc0dbc-44a7-4f94-890f-e85f248bbace/ZOOMX+VAPORFLY+NEXT%25+3+FK+PRM.png','626.43','2025-01-03 15:45:48.108934','2025-01-03 15:45:48.108934','running','men'),
	 ('68f12cea-30e4-4cf0-8ce1-46e010055997','Nike Pegasus Trail 5','{"benefits":[{"header":"Kick up","body":["An inscription of one the trail''s gnarly switchbacks heading down to the Canyon is hand-drawn on the tongue tops. The sockliners are detailed with some of the South Kaibab''s more memorable trail markers and the ever-present mules. Keep your eyes peeled for upper graphics that nod to the desert''s prickly plants."]},{"header":"Full bloom","body":["The speckled midsole is inspired by the route''s red dirt. The pops of purple speak to the trail''s super-bright cacti while the blues pay homage to the lake that once was."]},{"header":"More responsive","body":["The ReactX foam midsole is 13% more responsive than previous React technology. Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered."]},{"header":"Breathable for your run","body":["We placed mesh with tighter woven fabric in high-wear areas, like the toes. Mesh is combined with open holes on the upper for breathability."]},{"header":"All-direction traction","body":["Less rubber along the outsole compared to the previous iteration creates a smooth transition from road to trail while preserving the full-length ReactX midsole. A generative traction pattern combined with rubber in the forefoot provides extra grip for technical trails while maintaining a smooth ride for the road."]},{"header":"Secure feel","body":["Flywire technology integrates with the laces to help secure your midfoot."]}],"product_details":[{"header":"Product details","body":["Weight: 300 grams approx. (men''s UK 9)","Heel-to-toe drop: 9.5mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Armoury Navy/Vivid Grape/Green Frost/Phantom","Style: DV3864-401","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3b50d026-8a71-4355-bfb5-05f06e933a2e/NIKE+REACTX+PEGASUS+TRAIL+5.png','625.54','2025-01-03 15:45:48.113309','2025-01-03 15:45:48.113309','running','men'),
	 ('a3b0bb75-992a-4832-8483-4f943e6abeb9','Nike Invincible 3 Blueprint','{"benefits":[{"header":"Innovation is our inspiration","body":["Bill Bowerman, Nike''s original innovator, put our blueprint in place. He inspired the Blueprint collection design details, like the speckled Swoosh logo and sketches of feet on the insole. They remind us of where we''ve been as we keep moving forwards."]},{"header":"Support: high","body":["The more supportive the shoe, the more stability it can give to your natural stride. A combination of tuned support and intentionally placed cushioning helps you feel secure with every step. The Invincible 3 has high-support technology, with cushion and stability intentionally placed and shaped to protect your foot from the effects of pronation."]},{"header":"Cushioning: super-high","body":["The more cushioning that you have underfoot, the softer and more comfortable your running experience can be as your feet hit the ground. With Nike ZoomX cushioning shaped like a rocker and higher foam heights, this shoe gives you ultimate cushioning upon ground contact and an even softer underfoot feel."]},{"header":"Responsiveness: super-high","body":["The more responsive the shoe, the more energy return you can get back with each step. Whether you want to run a little bit faster or with a little less effort, responsive shoes help give you slightly more spring in your step to get more out of your run. Nike ZoomX foam is ultra-responsive and lightweight, giving you bounce and a snappy response with every step."]},{"header":"Fit: secure, breathable, comfortable","body":["An evolved Flyknit upper places zones of breathability where your foot heats up most. It''s strong and durable, helping keep your foot secure with every mile."]},{"header":"What''s new about the Invincible 3?","body":["We made the heel clip smaller than our previous iteration and placed it in a more precise location. A wider midsole adds stability. Taller foam stacks than our previous version raise the bar on cushioning and comfort, in a more sleek-looking design."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 309g (men''s size 9)","Heel-to-toe drop: 9mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Multi-Colour/Multi-Colour","Style: HJ6653-900","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/dc7cfec8-8653-43e9-9c94-c37e3ec93ae6/NIKE+ZOOMX+INVINCIBLE+RN+3+FP.png','902.01','2025-01-03 15:45:48.114885','2025-01-03 15:45:48.114885','running','men'),
	 ('8ae6b112-8cb6-4d61-9714-140d7a104ae8','Nike Pegasus Trail 4','{"benefits":[{"header":"Trail #440","body":["Once you hit trail #440, you know it''s nothing but iconic crystal-clear cascades, towering cliffs and lush Northwest rainforest landscape ahead. A misty green midsole takes its cues from the vibrant moss, ferns and trees while the deep blues speak to the tumbling mist cascading down the rugged, sky-high falls. And the dark reds come from the Douglas fir needles and fallen leaves that you tiptoe through along the trail''s towpaths."]},{"header":"Light, yet tough","body":["Runner-informed data was used to create and place engineered mesh throughout the upper for a sturdy, lightweight and breathable feel. We placed extra skins across the toes for durability."]},{"header":"Supportive steps","body":["Flywire technology is integrated with a midfoot band for total support that helps keep your foot in place."]},{"header":"Energised movement","body":["Nike React technology is a lightweight, durable foam that delivers a smooth, responsive ride."]},{"header":"Grip while you rip","body":["The rubber outsole has a generative traction pattern, created using data from runners like you. It gives your foot grip in key areas, helping you stay upright and stable over rocky trails, while also maintaining a smooth ride on the road."]},{"header":"Built to Resist Abrasion","body":["Rubber from the outsole wraps up onto the forefoot to help resist abrasion and provide more durability."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 289g (men''s size 9)","Heel-to-toe drop: 9.5mm","Not intended for use as personal protective equipment (PPE)","Colour Shown: Thunder Blue/Chlorophyll/Vapour Green/Light Armoury Blue","Style: DJ6158-403","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e6a98e6b-6727-4b87-aac2-d967eab7a532/NIKE+REACT+PEGASUS+TRAIL+4.png','538.13','2025-01-03 15:45:48.119788','2025-01-03 15:45:48.119788','running','men'),
	 ('979bf084-d011-4f47-aae0-77d051bfc96d','Nike Alphafly 3','{"benefits":[{"header":"Energy return for your marathon","body":["Two forefoot Air Zoom units combine with ZoomX foam to store and return the energy back to you, powering every step."]},{"header":"Propulsive feeling","body":["A full-length carbon-fibre plate delivers a propulsive sensation that helps you smoothly transition through every stride and tackle turns with confidence."]},{"header":"Cushioned ride","body":["Fully connected ZoomX foam creates an ultralight and cushioned feel, helping you stay fresh and comfortable from mile 1 to 26.2."]},{"header":"What''s new about the Alphafly 3?","body":["The Alphafly 3 is our lightest Alphafly ever, featuring a slightly wider carbon-fibre plate for increased stability, a fully connected ZoomX foam midsole for smoother transitions and an all-new AtomKnit upper designed for improved multi-directional containment and breathability."]}],"product_details":[{"header":"Product details","body":["Weight: 218g approx. (men''s UK 9)","Heel-to-toe drop: 8mm","Colour Shown: Volt/Dusty Cactus/Total Orange/Concord","Style: FD8311-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/7776f88c-1bf6-49ac-a53b-b532f4c51a87/AIR+ZOOM+ALPHAFLY+NEXT%25+3.png','333.07','2025-01-03 15:45:48.122227','2025-01-03 15:45:48.122227','running','men'),
	 ('ab09f419-e3ac-4562-a33c-7036faed79c3','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Smoke Grey/Iron Grey/Hot Punch/Photon Dust","Style: FN4322-003","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/43aad5f0-7d09-49f6-999d-8f6dd61f4d6a/NIKE+PRECISION+VII.png','408.46','2025-01-03 15:45:48.140552','2025-01-03 15:45:48.140552','basketball','women'),
	 ('577d3953-ddea-4029-9928-7f04e2624a73','Nike Interact Run EasyOn','{"benefits":[{"header":"To the future","body":["A scannable QR code on the tongue acts as your tour guide to the Interact Run''s performance benefits. It offers tips on how to extend the life cycle of your shoe from upkeep options to repairs and long-term care. Finally, when you''ve logged all the miles you can, the QR code will suggest ways to recycle and donate the shoes once they''ve run their course."]},{"header":"Made from Nike Grind","body":["The Waffle outsole is made from at least 13% Nike Grind material, crafted from scraps from the footwear-manufacturing process."]},{"header":"Soft ride","body":["The soft, responsive foam in the midsole gives you a comfortable, smooth ride for your run and wherever else your day takes you. The high foam heights provide a soft feel."]},{"header":"Fly away","body":["The Flyknit upper has zones of breathability where your foot heats up most, specifically in the toe box. It''s strong and durable, helping keep your foot secure with every mile. The airy and breezy upper hugs your feet in a free and easy way."]}],"product_details":[{"header":"Product details","body":["Weight: 269g approx. (men''s UK 9)","Heel-to-toe drop: 10mm","Colour Shown: Black/Black/White","Style: FV5590-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/187e02b8-726c-4546-aae2-4744dae0761c/NIKE+INTERACT+RUN+EASYON.png','910.77','2025-01-03 15:45:48.123641','2025-01-03 15:45:48.123641','running','men'),
	 ('f2ec89a2-11b4-4d4a-80af-4340cfe8ae2f','LeBron XXII ''Crown Jewel'' EP','{"benefits":[{"header":"Crown jewel","body":["This design has a gem-like glow—a bright-white upper with neon accents paired with a glow-in-the dark outsole at the forefoot. It reflects how the King embraces the pressures of being a professional athlete and a parent to win in all facets of his life."]},{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["Synthetic leather upper","Multi-directional traction pattern","Colour Shown: White/Medium Ash/Hot Lava/Volt Glow","Style: FZ1095-101","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/91a51763-80fe-488e-a5b2-8f9aff4c9794/LEBRON+XXII+EP.png','950.48','2025-01-03 15:45:48.125748','2025-01-03 15:45:48.125748','basketball','women'),
	 ('7232d1b6-7f0b-4434-8ae8-b48c6af3edc3','LeBron XXII ''Currency'' EP','{"benefits":[{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["A breathable dimensional mesh on the upper","Multi-directional traction pattern","Colour Shown: White/Green Glow/Pink Foam/Baltic Blue","Style: FZ1098-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/24a62e35-a0ac-4bdb-b864-1e6ca358bc3b/LEBRON+XXII+QS+EP.png','468.14','2025-01-03 15:45:48.126516','2025-01-03 15:45:48.126516','basketball','women'),
	 ('64f6e5b4-9e17-4cd4-b8e9-0bc087a0bcd2','Luka 3 PF ''Photo Finish''','{"benefits":[{"header":"Locked-in support","body":["Containment is key when you''re tearing down the court. A strong yet flexible plate runs up the sidewall to help keep your foot secure as you shift gears. To reduce the shoe''s weight, we removed excess areas of the plate, keeping only what was needed. The result? Locked-in support in one lightweight package."]},{"header":"Cushioning 3.0","body":["Acceleration is all about explosive movement, and for that you need cushioning that''s springy and supportive. Full-length Cushlon 3.0 foam helps you smoothly transition from heel to toe as you drive to the bucket, adding responsive energy to every step."]},{"header":"Lightweight Comfort","body":["A seamless moulded upper with a medial cut-out helps provide lightweight comfort and structure without feeling too tight in the forefoot. Pair that with a lighter plate and you have a shoe built to help you move as fast as you see the game."]},{"header":"Look fast, feel fast","body":["Built with speed in mind, these shoes draw inspiration from Luka''s love of cars and spinning tyres to give you lightning-fast style. Racing stripes adorn the pull tab while tyre-like details decorate the outsole."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: White/Volt Glow/Green Glow/Black","Style: HQ5055-107","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/04e752fb-1f6c-43c2-b617-6c076b2bca96/JORDAN+LUKA+3+PF.png','932.87','2025-01-03 15:45:48.131284','2025-01-03 15:45:48.131284','basketball','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('20501645-cbe1-4ad9-b18b-172b5d55c431','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Total Orange/Laser Orange/Photon Dust/Black","Style: FN4322-800","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3851856e-aa29-438d-9f49-048a7828663a/NIKE+PRECISION+VII.png','957.19','2025-01-03 15:45:48.135859','2025-01-03 15:45:48.135859','basketball','women'),
	 ('b9868842-3235-4869-a637-886973222a45','Nike Air Max Excee','{"benefits":[{"header":"Visible Air","body":["The Air-Sole unit is visible through 3 windows for an updated look."]},{"header":"Lightweight Comfort","body":["The foam midsole and outsole provide comfort without weighing you down."]},{"header":"Modern Look","body":["Elongated design lines honour the Air Max 90 while modernising it in a provocative way."]}],"product_details":[{"header":"Product Details","body":["Mesh, leather and suede upper with synthetic leather overlays","Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: White/Astronomy Blue/Wolf Grey/Black","Style: CD4165-120","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2e998fd3-25c2-418f-a3a9-88dbc901a1a9/NIKE+AIR+MAX+EXCEE.png','654.95','2025-01-03 15:45:48.101944','2025-01-03 15:45:48.101944','lifestyle','men'),
	 ('f056b1c8-b14e-4f05-bcd6-630cf84d86a4','Jordan Heir Series PF ''Her Collective''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in, do work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Pull tab on heel","Rubber outsole","Colour Shown: Black/Crimson Tint/Peach Cream/White","Style: FZ2473-018","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e1bb6e31-13e8-47e5-8ba5-5151a11e8ed4/WMNS+JORDAN+HEIR+SERIES+PF.png','312.82','2025-01-03 15:45:48.145035','2025-01-03 15:45:48.145035','basketball','women'),
	 ('d232bb9f-3490-4c10-a7c5-a70ee3915732','Nike Phantom Luna 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the pinky toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Fit for the pitch","body":["The anatomical mesh cuff offers soft comfort around your ankle and heel. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Sunset Pulse/Black","Style: FD6725-600","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d03f266b-f27a-492a-a038-bc49fe2c0bcc/PHANTOM+LUNA+II+ACADEMY+FG%2FMG.png','596.65','2025-01-03 15:45:48.150267','2025-01-03 15:45:48.150267','football','women'),
	 ('68dcd221-1c65-4d72-a259-a04c021528ab','Nike Mercurial Vapor 16 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8374-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2f196101-347d-4bf5-a86a-a816577eda22/ZOOM+VAPOR+16+ACADEMY+FG%2FMG.png','902.91','2025-01-03 15:45:48.153038','2025-01-03 15:45:48.153038','football','women'),
	 ('4ce4f1c2-d7a9-4e5d-9b2f-434ea469a920','Nike Mercurial Superfly 10 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ1454-400","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f71f58eb-ad7b-4495-acd0-163411f79298/ZM+SUPERFLY+10+ELITE+FG.png','873.66','2025-01-03 15:45:48.15449','2025-01-03 15:45:48.15449','football','women'),
	 ('c8ba55b2-2b67-4630-88d3-e79153d4851a','Nike Tiempo Legend 10 Elite','{"benefits":[{"header":"Brilliant Swoosh design","body":["Designed with the hard work of brilliance in mind, the textured Swoosh logo symbolises the friction that goes into polishing a gem before it shines. The Grey resembles the darkness you work under while the plate has an iridescent finish that represents your breakthrough moment when it''s time to shine. A gleaming upper along the side of the heel represents the shining light that breaks through the darkness."]},{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Not intended for use as personal protective equipment (PPE)","Cushioned insole","Colour Shown: Atmosphere Grey/Black","Style: FQ3250-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a8a13a14-c61c-4d1c-8ee2-756af9a36128/LEGEND+10+ELITE+FG+AS.png','633.66','2025-01-03 15:45:48.160846','2025-01-03 15:45:48.160846','football','women'),
	 ('9d368c06-64ab-4045-bd73-f170fd8c28a3','Nike React Phantom Run Flyknit 2','{"benefits":[{"header":"Smooth and Responsive","body":["Nike React technology delivers a soft, smooth, responsive ride. The shape of the foam midsole is all about zonal performance. It provides support for the 3 phases of a runner''s stride—flexibility at toe-off, a smooth ride at mid-stance and cushioning at contact."]},{"header":"Secure Feel","body":["The latest in Flywire technology features an elastic design that intertwines with the Flyknit upper, helping your foot feel secure as you run."]},{"header":"Lightweight and Breathable","body":["Flyknit Loft is the latest update to the popular material. 3 forefoot layers are combined for a lightweight, breathable and durable feel that keeps your foot comfortable."]}],"product_details":[{"header":"Product Details","body":["Increased rubber on the outsole helps deliver traction and durability.","Moulding around the heel keeps you secure so you can focus on your route.","Offset: 10mm (Forefoot: 18.5mm, Heel: 28.5mm)","Colour Shown: True White/White/Pure Platinum/Metallic Silver","Style: CJ0280-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/i1-268df378-99e9-4f60-9b4e-c18b9485bc91/W+NIKE+REACT+PHANTOM+RUN+FK+2.png','910.17','2025-01-03 15:45:48.223576','2025-01-03 15:45:48.223576','running','women'),
	 ('c3a4d371-e53d-4e2d-9bf4-ff297db54074','Nike Phantom Luna 2 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. The asymmetrical Flyknit cuff material provides snugness and shape around your ankle. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: White/Metallic Gold Coin/Black","Style: FJ2572-100","Country/Region of Origin: Bosnia \u0026 Herzegovina"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f1026add-f08b-47d8-84cb-40a8ba1194a1/PHANTOM+LUNA+II+ELITE+FG.png','846.20','2025-01-03 15:45:48.164755','2025-01-03 15:45:48.164755','football','women'),
	 ('f9ee3563-2fa4-4d36-90de-1f9bd6352bc0','Nike Phantom GX 2 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8003-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/22e2ecb5-63c9-474a-bc59-81c999a26d87/PHANTOM+GX+II+ELITE+FG.png','480.25','2025-01-03 15:45:48.16629','2025-01-03 15:45:48.16629','football','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('ce9f61c6-d0c9-4b99-ba94-0213c341e2a6','Nike Phantom Luna 2 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. The asymmetrical Flyknit cuff material provides snugness and shape around your ankle. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8002-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/641c2ad1-800d-469a-9b5b-55b69ec6be60/PHANTOM+LUNA+II+ELITE+FG.png','526.67','2025-01-03 15:45:48.167064','2025-01-03 15:45:48.167064','football','women'),
	 ('0934eae6-0f56-400f-a344-eb01b1a1049a','Nike Superfly 9 Elite Mercurial Dream Speed','{"benefits":[{"header":"Springy underfoot feel","body":["The 3/4-length Air Zoom unit sits in the outsole and provides another level of springy underfoot feel that helps you move fast on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change directions quickly and confidently. Heel studs provide traction and stability when braking. Off-centre studs at the toe give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and better fit in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium lining for optimal ball control at high speeds. The lining provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot. The pliability offers a more natural on-ball feel for dribbling, passing or scoring."]},{"header":"Drive your speed","body":["The speed cage inside of the structure is made from a thin but strong material that secures the foot to the outsole without adding weight."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Green Strike/Stadium Green/Black","Style: FJ7186-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bb40352b-540b-4437-b32f-fa0525626bd6/ZOOM+SUPERFLY+9+MDS+ELITE+FG.png','901.33','2025-01-03 15:45:48.170146','2025-01-03 15:45:48.170146','football','women'),
	 ('bec1a6f5-74c1-4597-8396-c4492033e522','Nike Air Max 97 Futura','{"benefits":[{"header":"Built for work ...","body":["The chunky outsole with a slight lift looks as good as it feels. Visible Max Air unit runs the length of the shoe for lightweight cushioning."]},{"header":"And play ...","body":["The upper combines leather, textile and suede for a layered look with a focus on comfort, style and durability."]},{"header":"And everything in between","body":["The past meets the future in this updated Futura icon. The upper keeps the fluid look of the original, while the redesigned hidden lacing system adds a fun twist."]}],"product_details":[{"header":"Product details","body":["Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: Glacier Blue/Crimson Tint/Guava Ice/Trace Blue","Style: FB4496-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b42c2a68-ab7b-41ed-aae0-cee4f6c2dd30/W+AIR+MAX+97+FUTURA.png','745.00','2025-01-03 15:45:48.200956','2025-01-03 15:45:48.200956','lifestyle','women'),
	 ('74859509-7bf8-4133-bf08-553b92ef1734','Nike Mercurial Vapor 15 Academy','{"benefits":[{"header":"Welcome to the pitch, Zoom","body":["For the 1st time in our history, Nike has developed an all-new Zoom Air unit. It sits in the outsole and provides an additional level of springy underfoot feel that helps you move faster on the pitch and create separation when it matters the most—whether you''re scoring goals, being first to the ball or going past defenders."]},{"header":"Drive your speed","body":["The speed cage inside the structure is made from a thin but strong material that secures the foot to the outsole without adding additional weight for optimal lockdown."]},{"header":"Dig in, take off","body":["Rubber outsole is designed for traction on turf surfaces."]},{"header":"Improved fit","body":["A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and better lockdown in the heel."]},{"header":"Feel the ball","body":["The upper has NikeSkin, a soft and flexible mesh material linked together by a thin coating. It helps provide ball control and truly gives you a feeling of barefoot football."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Lemonade/Black","Style: DJ5635-700","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/81c121db-746a-48b3-82c4-1e3811a9c015/ZOOM+VAPOR+15+ACADEMY+TF.png','958.61','2025-01-03 15:45:48.171578','2025-01-03 15:45:48.171578','football','women'),
	 ('952bf54f-a088-4bb1-9ffc-0b463400e06b','Nike Mercurial Superfly 10 Elite SE','{"benefits":[{"header":"Behind the design","body":["This special design blends some of the Mercurial''s best moments in the women''s game over the years. And for the first time in the Merc''s history, we''ve applied a never-before-seen Chrome finish to the plate and upper. It shines a light on the on and off-pitch excellence of women athletes who have helped shape the boot''s high-speed history."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Hyper Turquoise/Black","Style: FQ8309-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9de0f8f0-3dd2-4e36-88d3-a2d79e4769f6/ZM+SUPERFLY+10+ELITE+SE+FG.png','485.75','2025-01-03 15:45:48.174197','2025-01-03 15:45:48.174197','football','women'),
	 ('120ee34f-a9b4-4956-99ad-c538e593f40c','Nike Superfly 10 Academy Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1380-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/acf1c7f9-bebd-41fc-b81f-9af24b7e2ddb/ZM+SUPERFLY+10+ACAD+MDS+FG%2FMG.png','596.75','2025-01-03 15:45:48.175716','2025-01-03 15:45:48.175716','football','women'),
	 ('d987934b-9f84-46fd-8d91-1ee487ee8a9a','Nike Mercurial Superfly 10 Academy ''Kylian Mbappé''','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Light Laser Orange/Armoury Navy","Style: FQ8293-800","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bcaf1d52-6ec4-4acb-a7a5-48a685aac77f/ZM+SUPERFLY+10+ACAD+KM+FG%2FMG.png','430.00','2025-01-03 15:45:48.179293','2025-01-03 15:45:48.179293','football','women'),
	 ('235db861-c148-49fe-865f-b89a7e01d00c','Nike C1TY','{"benefits":[{"header":"Breathable and durable","body":["With a reinforced rubber side wall and rugged toe box, the breathable upper pairs suede and mesh to keep you cool under pressure."]},{"header":"Secure comfort","body":["Cupsole construction and flexible foam work together to provide round-the-clock comfort and support."]},{"header":"Versatile traction","body":["Dual-stiffness Waffle outsole with rubber lugs delivers supreme grip across all city surfaces."]}],"product_details":[{"header":"Product details","body":["Foam midsole","Rubber outsole","Colour Shown: Summit White/Fire Red/Black","Style: FZ3863-101","Country/Region of Origin: India"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5d4ed0e0-7df0-4a31-8a40-aacf8462c39e/NIKE+C1TY.png','795.74','2025-01-03 15:45:48.204357','2025-01-03 15:45:48.204357','lifestyle','women'),
	 ('ad66e5fa-bc09-4a02-9a37-41131907859f','Nike Mercurial Superfly 10 Elite ''Kylian Mbappé''','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time. The Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Light Laser Orange/Armoury Navy","Style: FQ8692-800","Country/Region of Origin: Bosnia \u0026 Herzegovina"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/737e6beb-15b3-4950-9c82-a642b67c1bfb/ZM+SUPERFLY+10+ELITE+KM+FG.png','777.40','2025-01-03 15:45:48.181099','2025-01-03 15:45:48.181099','football','women'),
	 ('bcad0e89-14a0-4df6-bac5-b578012fd4a5','Air Jordan 1 Low','{"benefits":[{"header":"High-End Materials","body":["For this go, the Low features a high-end mix of leather and synthetic materials in the upper."]},{"header":"Air Within","body":["An Air unit is encapsulated in the heel, giving you lightweight cushioning that''s been a sensation for more than a generation."]},{"header":"Timeless Trims","body":["The Wings logo on the heel and a Jumpman design on the tongue make this a shoe with iconic details."]}],"product_details":[{"header":"Product details","body":["Wings logo on the heel","Stitched Swoosh design","Perforated toe","Foam midsole","Rubber traction","Colour Shown: Sail/Coconut Milk/Neutral Grey","Style: DC0774-103","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/760f2052-c40b-452d-8ef9-1010964f182e/WMNS+AIR+JORDAN+1+LOW.png','537.94','2025-01-03 15:45:48.183493','2025-01-03 15:45:48.183493','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('cfa6e134-7d1a-4828-8805-4ee095b250e9','Nike Air Max Furyosa NRG','{"benefits":[{"header":"Be bold, be comfortable","body":["Stacked, visible and offset: the Nike Air cushioning in the heel delivers a new look that adds comfort to your journey."]},{"header":"Wear what you demand","body":["Higher arch support, a wider forefoot and a lowered ankle scoop—it''s specifically designed for the unique shape of a woman''s foot and delivers the perfect fit straight out of the box."]},{"header":"Be spontaneous","body":["The dual-lacing system lets you be as expressive as you want. Wrap it, lace it, bow it or remove it to fit your style."]},{"header":"Step into luxury","body":["The layered design builds a shoe within a shoe, giving you the luxury feel of a slipper. The heel pillow, ultra-plush tongue and padded collar feel great while maintaining a modern look."]}],"product_details":[{"header":"Product details","body":["Pull tabs","''90s-style branding","Not intended for use as personal protective equipment (PPE)","Colour Shown: Sail/Phantom/Platinum Violet/Black","Style: DC7350-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/64d46d2b-be66-45b3-99e6-d4c5f627ec98/W+AIR+MAX+FURYOSA+NRG.png','722.49','2025-01-03 15:45:48.184202','2025-01-03 15:45:48.184202','lifestyle','women'),
	 ('92454ebb-4bdc-4138-b12c-2ff3c6a25429','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Colour Shown: White/Blue Void/Metallic Silver/Bright Crimson","Style: FV2250-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e61080a2-fbe3-4bd9-917b-673bb10f6c73/AIR+MAX+DN+OLY.png','706.43','2025-01-03 15:45:48.188643','2025-01-03 15:45:48.188643','lifestyle','women'),
	 ('11f441c6-ff5d-473f-b6e2-50290ef8ab80','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Black/Metallic Dark Grey/Black","Style: DV3337-006","Country/Region of Origin: Indonesia, Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/35c07f69-1d7a-4272-abe4-4adf4b9a9d2f/AIR+MAX+DN.png','683.70','2025-01-03 15:45:48.193446','2025-01-03 15:45:48.193446','lifestyle','women'),
	 ('a8496f4c-ddac-423f-a7bd-96361701b58e','Nike Air Max Dn SE','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Glossy accents","Foam midsole","Rubber outsole","Colour Shown: Pink Foam/Metallic Silver/White/White","Style: HJ9636-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/627dcb0a-88bf-4ab9-aeca-539b396baaea/W+AIR+MAX+DN+SE.png','999.27','2025-01-03 15:45:48.199393','2025-01-03 15:45:48.199393','lifestyle','women'),
	 ('bf3f4460-be5e-4cfe-8c91-df0fe8db2107','Nike Vaporfly 3','{"benefits":[{"header":"Propelling you forwards","body":["A full-length carbon fibre flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ride","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft, yet supportive yarns deliver our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 165g (women''s size 6)","Heel-to-toe drop: 8mm","Wider toe area for a roomier fit","Internal foam pod on the heel for extra cushioning","Colour Shown: Volt/Scream Green/Barely Volt/Black","Style: DV4130-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/efcb2629-34c7-484a-9a76-86959a52b272/W+NIKE+ZOOMX+VAPORFLY+NEXT%25+3.png','500.93','2025-01-03 15:45:48.210013','2025-01-03 15:45:48.210013','running','women'),
	 ('bd4dee68-d821-4e1f-9cf3-255a87dac3a9','Nike Interact Run EasyOn SE','{"benefits":[{"header":"Made from Nike Grind","body":["The Waffle outsole is made from at least 13% Nike Grind material, crafted from scraps from the footwear-manufacturing process."]},{"header":"Soft ride","body":["The soft, responsive foam in the midsole gives you a comfortable, smooth ride for your run and wherever else your day takes you. The high foam heights provide a soft feel."]},{"header":"Fly away","body":["The Flyknit upper has zones of breathability where your foot heats up most, specifically in the toe box. It''s strong and durable, helping keep your foot secure with every mile. The airy and breezy upper hugs your feet in a free and easy way."]}],"product_details":[{"header":"Product details","body":["Weight: 214 grams approx. (women''s UK 5.5)","Heel-to-toe drop: 10mm","Colour Shown: Wolf Grey/Barely Volt/Multi-Colour/White","Style: HQ2698-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bb0daff2-c144-40a5-bd54-3325182c377c/W+NIKE+INTERACT+RUN+EASYON+SE.png','526.21','2025-01-03 15:45:48.211536','2025-01-03 15:45:48.211536','running','women'),
	 ('234292db-9ce7-4d71-b348-7eec7c9667c7','Nike Pegasus Trail 5','{"benefits":[{"header":"Extra Cushioning","body":["Nike ReactX foam in the midsole gives you extra cushioning."]},{"header":"Breathable for your run","body":["We placed engineered mesh with tighter woven fabric in high-wear areas, like the toes. The engineered mesh is combined with open holes on the upper for breathability. Plus, Flywire technology integrates with the laces to help secure your midfoot."]},{"header":"All-direction traction","body":["Less rubber along the outsole compared to the previous iteration creates a smooth transition from road to trail while preserving the full-length ReactX midsole. Plus, it wraps around the front of the shoe to provide extra durability. A generative traction pattern combined with rubber in the forefoot provides extra grip for technical trails while maintaining a smooth ride for the road."]}],"product_details":[{"header":"Product details","body":["Weight: 243 grams approx. (women''s UK 6)","Heel-to-toe drop: 9.5mm","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Anthracite/Wolf Grey/White","Style: DV3865-001","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5c2f0db0-9338-48ed-9112-bbe60ee32bcf/W+NIKE+REACTX+PEGASUS+TRAIL+5.png','817.40','2025-01-03 15:45:48.214407','2025-01-03 15:45:48.214407','running','women'),
	 ('b52a09e7-000b-4f3c-90b3-6f9519de863a','Nike Pegasus Trail 5','{"benefits":[{"header":"Extra Cushioning","body":["Nike ReactX foam in the midsole gives you extra cushioning."]},{"header":"Breathable for your run","body":["We placed engineered mesh with tighter woven fabric in high-wear areas, like the toes. The engineered mesh is combined with open holes on the upper for breathability. Plus, Flywire technology integrates with the laces to help secure your midfoot."]},{"header":"All-direction traction","body":["Less rubber along the outsole compared to the previous iteration creates a smooth transition from road to trail while preserving the full-length ReactX midsole. Plus, it wraps around the front of the shoe to provide extra durability. A generative traction pattern combined with rubber in the forefoot provides extra grip for technical trails while maintaining a smooth ride for the road."]}],"product_details":[{"header":"Product details","body":["Weight: 243 grams approx. (women''s UK 6)","Heel-to-toe drop: 9.5mm","Not intended for use as personal protective equipment (PPE)","Colour Shown: Phantom/Picante Red/Black/Sail","Style: DV3865-003","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1856b680-4e0e-4ccc-a594-c56b62720b0c/W+NIKE+REACTX+PEGASUS+TRAIL+5.png','350.08','2025-01-03 15:45:48.218957','2025-01-03 15:45:48.218957','running','women'),
	 ('b980140a-949d-401c-acd9-c65947d664f5','Nike Vaporfly 3','{"benefits":[{"header":"Propelling you forwards","body":["A full-length carbon-fibre Flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ride","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft yet supportive yarns delivers our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 165 grams (women''s size 5.5)","Heel-to-toe drop: 8mm","Colour Shown: Mint Foam/Sunset Tint/Barely Volt/Sail","Style: HQ3505-379","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/33b7edd5-bc94-4929-b897-67ce249c69ce/W+ZOOMX+VAPORFLY+NEXT%25+3FK.png','497.62','2025-01-03 15:45:48.221062','2025-01-03 15:45:48.221062','running','women'),
	 ('e035707f-0270-451b-a219-f2f7db585af0','Nike Streetgato','{"benefits":[{"header":"Grip and Go","body":["Redesigned outsole provides non-stop traction for small-sided games."]},{"header":"Streetwear Performance","body":["The suede in the uppers offers an everyday look whether you''re playing on the street or keeping things casual."]}],"product_details":[{"header":"Product details","body":["Rubber outsole","Colour Shown: Deep Jungle/Green Frost","Style: DC8466-302","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/87e0c6d4-de2c-4b3c-b48f-e7f535db5ff9/NIKE+STREETGATO.png','717.80','2025-01-03 15:45:47.99524','2025-01-03 15:45:47.99524','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('c5469f58-404a-4573-8a10-7ab4bc790ba3','Nike Juniper Trail 3','{"benefits":[{"header":"All-terrain ready","body":["The Nike Trail ATC outsole is made from an all-terrain compound that''s great even in wet weather. It provides grip on any surface while maintaining durability and a smooth ride on the road."]},{"header":"Smooth Ride","body":["The full-length foam midsole provides a soft and cushioned ride. A flexible midfoot system connects the upper and midsole for increased support and stability."]},{"header":"Soft touch","body":["We''ve softened the touch points along the collar foam and tongue to help minimise distractions."]},{"header":"Comfort and Containment","body":["Durable mesh provides comfort and containment."]}],"product_details":[{"header":"Product details","body":["Weight: 272g approx. (women''s size 5.5)","Heel-to-toe drop: 10mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Platinum Violet/Light Violet Ore/Armoury Navy/Metallic Silver","Style: FQ0902-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/77f54309-4f73-4323-8d8f-917fc5c8e902/W+NIKE+JUNIPER+TRAIL+3.png','440.68','2025-01-03 15:45:48.227479','2025-01-03 15:45:48.227479','running','women'),
	 ('77ed7154-2635-427b-b5e2-838605c69d4e','Nike Zegama 2','{"benefits":[{"header":"Stay sticky","body":["Vibram Zegama outsole made with Vibram Megagrip has a diverse lug pattern highlighted with wide spacing. This means you get traction for more technical terrains."]},{"header":"Keep running","body":["A lightweight Nike ZoomX midsole is combined with increased stack heights to help provide cushioning during extended stretches of running."]},{"header":"Stable for trails","body":["Engineered mesh—stronger and more flexible than normal mesh—on the upper helps provide stability for various trail conditions."]}],"product_details":[{"header":"Product details","body":["Weight: 264g approx. (Women''s UK 5.5)","Heel-to-toe drop: 4mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Daybreak/Cosmic Clay/Sundial/White","Style: FD5191-502","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/996afa1b-73a2-423e-a982-8dd7df14b0da/W+NIKE+ZOOMX+ZEGAMA+TRAIL+2.png','605.06','2025-01-03 15:45:48.23031','2025-01-03 15:45:48.23031','running','women'),
	 ('e657cdc4-d52b-49ea-a8ca-dac8febd2545','Nike React Phantom Run Flyknit 2','{"benefits":[{"header":"Smooth and Responsive","body":["Nike React technology delivers a soft, smooth, responsive ride. The shape of the foam midsole is all about zonal performance. It provides support for the 3 phases of a runner''s stride—flexibility at toe-off, a smooth ride at mid-stance and cushioning at contact."]},{"header":"Secure Feel","body":["The latest in Flywire technology features an elastic design that intertwines with the Flyknit upper, helping your foot feel secure as you run."]},{"header":"Lightweight and Breathable","body":["Flyknit Loft is the latest update to the popular material. 3 forefoot layers are combined for a lightweight, breathable and durable feel that keeps your foot comfortable."]}],"product_details":[{"header":"Product Details","body":["Increased rubber on the outsole helps deliver traction and durability.","Moulding around the heel keeps you secure so you can focus on your route.","Offset: 10mm (Forefoot: 18.5mm, Heel: 28.5mm)","Colour Shown: Teal Tint/Aurora Green/White","Style: CJ0280-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/74934ec7-4f8f-4946-9322-c72346061cb3/W+NIKE+REACT+PHANTOM+RUN+FK+2.png','514.63','2025-01-03 15:45:48.233163','2025-01-03 15:45:48.233163','running','women'),
	 ('943405ba-96fd-461b-b75c-230f1c9e47ea','Nike Vaporfly 3 ''Eliud Kipchoge''','{"benefits":[{"header":"Keep growing","body":["Whenever someone trains with Eliud Kipchoge, they''re asked to plant a tree at his base camp to signify their growth. The sockliner graphics mimic that growth with branches moving forwards towards the front of the shoe. The Red Clay colour fade nods to the Kenyan dirt that stains the shoes when training. The font is a play on African trees that have fractal-like patterns on the surfaces."]},{"header":"Propelling you forwards","body":["A full-length carbon-fibre Flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ready","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft, yet supportive yarns deliver our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 200 grams (men''s size 9)","Heel-to-toe drop: 8mm","World Athletics-approved","Wider toe area for a roomier fit","Internal foam pod on the heel for extra cushioning","Wear-tested number on the outsole","Colour Shown: Vapour Green/Dragon Red/Stadium Green/Black","Style: HJ7040-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/eb6cdeee-ef8c-4a7e-bd77-5dbc5843f6d4/ZOOMX+VAPORFLY+NEXT%25+3+FK+EK.png','570.61','2025-01-03 15:45:47.990612','2025-01-03 15:45:47.990612','running','men'),
	 ('598c2065-9b26-4311-a094-d711b2244266','Nike Mercurial Superfly 9 Elite','{"benefits":[{"header":"Brilliant Swoosh design","body":["Designed with the hard work of brilliance in mind, the textured Swoosh logo symbolises the friction that goes into polishing a gem before it shines. The Grey resembles the darkness you work under while the plate has an iridescent finish that represents your breakthrough moment when it''s time to shine."]},{"header":"Zoom, zoom","body":["The 3/4-length Air Zoom unit sits in the outsole and provides another level of springy underfoot feel that helps you move fast on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change direction quickly and confidently. Heel studs provide traction and stability when braking. Toe-off centre studs give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and a better fit in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium lining for optimal ball control at high speeds. The lining provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot. The pliability offers a more natural on-ball feel for shooting, dribbling or passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Not intended for use as personal protective equipment (PPE)","Cushioned insole","Colour Shown: Atmosphere Grey/Black","Style: FN5613-001","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/25cc3c76-9257-48f7-9908-2a9443c49e88/ZOOM+SUPERFLY+9+ELITE+FG+AS.png','373.90','2025-01-03 15:45:47.991682','2025-01-03 15:45:47.991682','football','women'),
	 ('dccd4bd1-9abb-404e-b8ce-9fef2d6d9a45','Nike Streetgato','{"benefits":[{"header":"Grip and Go","body":["Redesigned outsole provides non-stop traction for small-sided games."]},{"header":"Streetwear Performance","body":["The suede in the uppers offers an everyday look whether you''re playing on the street or keeping things casual."]}],"product_details":[{"header":"Product details","body":["Rubber outsole","Colour Shown: Red Stardust/Red Stardust","Style: DC8466-602","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b232594a-e886-444e-84d2-64be8806544d/NIKE+STREETGATO.png','462.95','2025-01-03 15:45:47.992521','2025-01-03 15:45:47.992521','football','women'),
	 ('cfade3a5-2c3b-42e0-ad28-aa7f198c62de','Nike Vapor 16 Elite Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1392-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/451d1501-2758-4c49-bcd8-a7defcc5b5ab/ZOOM+VAPOR+16+ELITE+MDS+FG.png','787.40','2025-01-03 15:45:47.993514','2025-01-03 15:45:47.993514','football','women'),
	 ('c1765b65-193f-4839-bd65-0965ee621182','LeBron XXII ''Currency'' EP','{"benefits":[{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["A breathable dimensional mesh on the upper","Multi-directional traction pattern","Colour Shown: White/Green Glow/Pink Foam/Baltic Blue","Style: FZ1098-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/24a62e35-a0ac-4bdb-b864-1e6ca358bc3b/LEBRON+XXII+QS+EP.png','573.11','2025-01-03 15:45:47.994427','2025-01-03 15:45:47.994427','basketball','men'),
	 ('8ba4aa11-1768-4649-b484-b90c6e9d1b17','Jordan One Take 5 PF','{"benefits":[{"header":"Containment for days","body":["The upper, eyestay and wraparound toe piece combine to help give you the on-court containment your game needs."]},{"header":"Up-front response","body":["The Zoom Air unit in the forefoot is top-loaded, bringing the responsive sensation closer to your foot when you''re driving hard down the court."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Embroidered tongue logo","Jumpman on the midsole","Colour Shown: Black/Anthracite/Sail/Taxi","Style: FD2336-007","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/40ed29c0-da68-4c05-abaa-4acdebdf4a12/JORDAN+ONE+TAKE+5+PF.png','800.12','2025-01-03 15:45:47.998447','2025-01-03 15:45:47.998447','basketball','men'),
	 ('f5d532cd-ee36-45ce-8ce1-79516ae87b91','LeBron XXII ''Crown Jewel'' EP','{"benefits":[{"header":"Crown jewel","body":["This design has a gem-like glow—a bright-white upper with neon accents paired with a glow-in-the dark outsole at the forefoot. It reflects how the King embraces the pressures of being a professional athlete and a parent to win in all facets of his life."]},{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["Synthetic leather upper","Multi-directional traction pattern","Colour Shown: White/Medium Ash/Hot Lava/Volt Glow","Style: FZ1095-101","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/91a51763-80fe-488e-a5b2-8f9aff4c9794/LEBRON+XXII+EP.png','600.29','2025-01-03 15:45:47.999121','2025-01-03 15:45:47.999121','basketball','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('b3dfd261-711b-46b7-8179-fbd29a3890cb','Tatum 3 PF ''Zen''','{"benefits":[{"header":"Conforms to your moves","body":["A contouring fit offers stretch and containment. We studied players in action and layered materials in the upper where it mattered most. The result? Shoes designed to keep up with your game."]},{"header":"Lightest in flight","body":["Less weight means more speed, and we''re all about speed. A flexible textile upper helps Tatum''s latest signature shoe continue the line''s reign as the lightest performance shoes in our collection—now that''s champ talk."]},{"header":"Traction for quick cuts","body":["The Cushlon foam and a springy Air Zoom unit help provide a smooth ride underfoot. They work alongside a firm frame to help you feel secure whether you''re getting up or making quick cuts."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Platinum Tint/Particle Grey/Grey Fog/Black","Style: FZ6601-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/4aa50aaf-1393-4c1d-8eb3-db2a1fb16714/JORDAN+TATUM+3+PF.png','489.04','2025-01-03 15:45:48.002132','2025-01-03 15:45:48.002132','basketball','men'),
	 ('78bd5704-876f-484f-bf08-81087cec4fe5','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: Barely Green/Jade Ice/Metallic Red Bronze/Vapour Green","Style: DD9304-301","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f8a23de7-3b97-40d4-910d-a8ed2099d0a0/NIKE+RENEW+ELEVATE+III.png','618.26','2025-01-03 15:45:48.003019','2025-01-03 15:45:48.003019','basketball','men'),
	 ('0a5bf2e9-c06f-41bc-8aa8-afb7abee6e23','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Black/University Red/White","Style: FN4322-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e6cad6b9-b122-49d4-b15b-a504180b5a6c/NIKE+PRECISION+VII.png','557.13','2025-01-03 15:45:48.004583','2025-01-03 15:45:48.004583','basketball','men'),
	 ('76384493-993c-4306-b935-34484626d9ad','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: White/Pure Platinum/Black","Style: DD9304-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5ba3b10c-b59c-4c7b-af60-71276ffe1f03/NIKE+RENEW+ELEVATE+III.png','414.88','2025-01-03 15:45:48.005943','2025-01-03 15:45:48.005943','basketball','men'),
	 ('390e38f8-8888-465d-93d4-e8622d496e07','Nike Precision 7 EasyOn','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: White/Sport Red/Obsidian","Style: FN0324-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3c52aed2-e595-452d-b031-753d7a301e63/NIKE+PRECISION+VII+EASYON.png','415.35','2025-01-03 15:45:48.007338','2025-01-03 15:45:48.007338','basketball','men'),
	 ('ccfb3542-6556-4cd2-a445-a0bcd6b5863f','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Volt/Summit White/Barely Volt/Dark Smoke Grey","Style: FN4322-700","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/97fb8db1-8d01-451e-8dbf-5009b2cc2a79/NIKE+PRECISION+VII.png','566.17','2025-01-03 15:45:48.008006','2025-01-03 15:45:48.008006','basketball','men'),
	 ('107d4f5b-b311-4c4d-8cb1-b46d1275435f','Air Jordan XXXIX PF ''Sol''','{"benefits":[{"header":"All play with no crash","body":["We added a crash pad at the instep to help hold your foot in place and keep your toes from slamming into the toe box. After all, just because MJ lost a few toenails, it doesn''t mean you should have to."]},{"header":"Zoom into comfort","body":["ZoomX foam, Nike''s lightest high-efficiency foam, contours to the natural shape of your foot to give you soft and springy cushioning without weighing you down. We paired it with a full-length Air Zoom unit for snappy energy return."]},{"header":"Rock solid","body":["Remember MJ''s cross step? Of course you do. It influenced this shoe from the sole up. A built-in sidewall cupsole helps provide stability during lateral movements and allows for full engagement of the underfoot cushioning."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Black/University Red","Style: FQ0214-106","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7a27a0ad-619b-4f93-86b4-b997803b74c0/AIR+JORDAN+XXXIX+PF.png','968.96','2025-01-03 15:45:48.010692','2025-01-03 15:45:48.010692','basketball','men'),
	 ('0fc10848-d6b0-47df-a5ef-5b0e032dcaaa','Tatum 2 PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Hyper Jade/White/Hyper Pink/Green Strike","Style: HJ4421-303","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/cfcf17cb-9e73-4294-9513-d8c6f9d73c72/JORDAN+TATUM+2+GPX+PF.png','312.99','2025-01-03 15:45:48.01137','2025-01-03 15:45:48.01137','basketball','men'),
	 ('e92d2b13-1f44-4240-8559-5abbbbf68707','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: White/Black","Style: FN4322-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0351925a-de56-4051-92bd-b4e88149e953/NIKE+PRECISION+VII.png','536.14','2025-01-03 15:45:48.012032','2025-01-03 15:45:48.012032','basketball','men'),
	 ('d826d906-36f1-4671-b703-c8a9d0c7f267','Jordan Heir Series PF ''Classic''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in and work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","Rubber outsole","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Sail/Metallic Gold","Style: FQ3859-007","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b227d57b-4ed8-4c1b-99d0-f2b062e500a3/JORDAN+HEIR+SERIES+PF.png','732.64','2025-01-03 15:45:48.012678','2025-01-03 15:45:48.012678','basketball','men');
