	 ('fe955eaf-056c-46ca-8128-ac253b43d44b','Zion 3 PF ''Liquid Metal''','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Pure Platinum/Metallic Silver/University Red","Style: DR0676-016","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/f9c58f01-fc40-4ada-b86c-1ec2ea8a35c6/JORDAN+ZION+3+PF.png','549.52','2025-01-03 15:45:48.016596','2025-01-03 15:45:48.016596','basketball','men'),
	 ('912d7227-caa4-403b-bed1-768a27fdb9a7','Jordan Heir Series PF ''White/Black Volt''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in and work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["Pull tab on heel","Rubber outsole","The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Sail/Volt/Black","Style: FQ3859-107","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/da518c33-7e1d-408e-b192-0fa60a928391/JORDAN+HEIR+SERIES+PF.png','530.31','2025-01-03 15:45:48.017302','2025-01-03 15:45:48.017302','basketball','men'),
	 ('a80223eb-0f99-4081-afe3-342d48eadcb9','Jordan One Take 5 PF','{"benefits":[{"header":"Containment for days","body":["The upper, eyestay and wraparound toe piece combine to help give you the on-court containment your game needs."]},{"header":"Up-front response","body":["The Zoom Air unit in the forefoot is top-loaded, bringing the responsive sensation closer to your foot when you''re driving hard down the court."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Embroidered tongue logo","Jumpman on the midsole","Colour Shown: White/Black/Legend Blue","Style: FD2336-104","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e3302bdb-8dd6-4cbb-9ca8-f8598a9c9412/JORDAN+ONE+TAKE+5+PF.png','769.63','2025-01-03 15:45:48.019421','2025-01-03 15:45:48.019421','basketball','men'),
	 ('146584eb-da3a-4bba-bcd9-a81a04caa452','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Black/Iron Grey/Smoke Grey/White","Style: FN4322-005","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/738aa0dc-403b-45fa-bbca-874a3b3e411d/NIKE+PRECISION+VII.png','974.84','2025-01-03 15:45:48.020085','2025-01-03 15:45:48.020085','basketball','men'),
	 ('79985e2c-0981-40a1-a768-2361aa369356','Tatum 2 PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Blue Void/Leche Blue/Tropical Twist/Bleached Coral","Style: HJ4421-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/30648388-71e0-4cd0-b2b3-72e5c458ec58/JORDAN+TATUM+2+GPX+PF.png','715.76','2025-01-03 15:45:48.021433','2025-01-03 15:45:48.021433','basketball','men'),
	 ('19df1fbb-f48b-4e05-8f2c-0dca225e7d46','Tatum 3 PF ''Welcome to the Garden''','{"benefits":[{"header":"Conforms to your moves","body":["A contouring fit offers stretch and containment. We studied players in action and layered materials in the upper where it mattered most. The result? Shoes designed to keep up with your game."]},{"header":"Lightest in flight","body":["Less weight means more speed, and we''re all about speed. A flexible textile upper helps Tatum''s latest signature shoe continue the line''s reign as the lightest performance shoes in our collection—now that''s champ talk."]},{"header":"Traction for quick cuts","body":["The Cushlon foam and a springy Air Zoom unit help provide a smooth ride underfoot. They work alongside a firm frame to help you feel secure whether you''re getting up or making quick cuts."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Kinetic Green/Black","Style: FZ6601-103","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d57e5066-b53b-4f9b-bd37-37d4c01b41a9/JORDAN+TATUM+3+PF.png','906.96','2025-01-03 15:45:48.02275','2025-01-03 15:45:48.02275','basketball','men');
