	 ('78ac816e-1b5e-4be7-8785-c9e4b6993602','Jordan One Take 5 Quai 54 PF','{"benefits":[{"header":"Containment for days","body":["Feel supported and secure during game play with a design that prioritises on-court containment."]},{"header":"Up-front response","body":["Top-loaded Zoom Air unit helps bring responsive cushioning closer to your foot when you''re driving hard down the court."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Embroidered tongue logo","Jumpman on the midsole","Colour Shown: Summit White/Off-Noir/Burnt Sunrise/Game Royal","Style: HF0017-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/5c2d5d73-ca65-41bc-b165-908c1ed77774/JORDAN+ONE+TAKE+5+Q54+PF.png','735.27','2025-01-03 15:45:48.024817','2025-01-03 15:45:48.024817','basketball','men'),
