	 ('2861afd0-7b2e-4132-a5a6-71b040c91bd5','Tatum 3 PF ''Welcome to the Garden''','{"benefits":[{"header":"Conforms to your moves","body":["A contouring fit offers stretch and containment. We studied players in action and layered materials in the upper where it mattered most. The result? Shoes designed to keep up with your game."]},{"header":"Lightest in flight","body":["Less weight means more speed, and we''re all about speed. A flexible textile upper helps Tatum''s latest signature shoe continue the line''s reign as the lightest performance shoes in our collection—now that''s champ talk."]},{"header":"Traction for quick cuts","body":["The Cushlon foam and a springy Air Zoom unit help provide a smooth ride underfoot. They work alongside a firm frame to help you feel secure whether you''re getting up or making quick cuts."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Kinetic Green/Black","Style: FZ6601-103","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d57e5066-b53b-4f9b-bd37-37d4c01b41a9/JORDAN+TATUM+3+PF.png','405.32','2025-01-03 15:45:48.026903','2025-01-03 15:45:48.026903','basketball','men'),
	 ('5000fde2-dca2-49e2-b0d1-cde2530098d2','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: Barely Green/Jade Ice/Metallic Red Bronze/Vapour Green","Style: DD9304-301","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f8a23de7-3b97-40d4-910d-a8ed2099d0a0/NIKE+RENEW+ELEVATE+III.png','691.37','2025-01-03 15:45:48.028261','2025-01-03 15:45:48.028261','basketball','men'),
	 ('afdd7fe6-90fc-43dc-b235-37f886daca6e','Tatum 2 ''Vortex'' PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight Build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Mint Foam/Black/Hyper Jade/Lava Glow","Style: FJ6458-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d53a40e2-c781-416a-aa91-0434582290da/JORDAN+TATUM+2+PF.png','442.37','2025-01-03 15:45:48.034223','2025-01-03 15:45:48.034223','basketball','men'),
	 ('7d0866a4-e59f-4d7c-8a37-f9bf92714840','Air Jordan XXXIX PF','{"benefits":[{"header":"All play with no crash","body":["We added a crash pad at the instep to help hold your foot in place and keep your toes from slamming into the toe box. After all, just because MJ lost a few toenails, it doesn''t mean you should have to."]},{"header":"Zoom into comfort","body":["ZoomX foam, Nike''s lightest high-efficiency foam, contours to the natural shape of your foot to give you soft and springy cushioning without weighing you down. We paired it with a full-length Air Zoom unit for snappy energy return."]},{"header":"Rock solid","body":["Remember MJ''s cross step? Of course you do. It influenced this shoe from the sole up. A built-in sidewall cupsole helps provide stability during lateral movements and allows for full engagement of the underfoot cushioning."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Black/Sail","Style: FQ0214-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/c5583daa-464a-4172-a060-fd434277c05a/AIR+JORDAN+XXXIX+PF.png','863.14','2025-01-03 15:45:48.028915','2025-01-03 15:45:48.028915','basketball','men'),
	 ('23bd8e7a-bbbe-4b42-a3d4-8a49d55fb1e4','Nike Tiempo Legend 10 Club','{"benefits":[{"header":"Amplified touch","body":["The moulded synthetic leather mimics a quilted sensation for improved touch."]},{"header":"Natural, contouring fit","body":["The synthetic leather moulds to your foot and gives you better control, helping you stay comfortable for your match."]},{"header":"Traction for the Court","body":["The pattern on the outsole gives you traction for street, court and indoor surfaces."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Mesh tongue","Cushioned insole","Colour Shown: Soar/White","Style: DV4343-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8959d2c5-ea3a-4982-871f-bae185fa74cc/LEGEND+10+CLUB+IC.png','362.59','2025-01-03 15:45:48.031706','2025-01-03 15:45:48.031706','football','men'),
	 ('7872cefb-9a98-4aac-804d-18da2274dd2e','Luka 2 PF','{"benefits":[{"header":"Cushioned for Impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-Step Efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral side wall, complemented by a firm foam carrier and Formula 23 foam in the midsole."]},{"header":"360 Degrees of Support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product Details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Volt/White","Style: DX9012-017","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/f82558ed-76b4-488e-9bf7-06f687478a23/JORDAN+LUKA+2+PF.png','793.52','2025-01-03 15:45:48.032348','2025-01-03 15:45:48.032348','basketball','men');
