	 ('164f0b0f-1fc5-42fd-89e2-d7d5f7b380c5','Nike Tiempo Legend 10 Club','{"benefits":[{"header":"Amplified touch","body":["The moulded synthetic leather mimics a quilted sensation for improved touch."]},{"header":"Natural, contouring fit","body":["The synthetic leather moulds to your foot and gives you better control, helping you stay comfortable for your match."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4344-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ec2b2eb3-a34f-4411-a6d9-fc218ef848ef/LEGEND+10+CLUB+FG%2FMG.png','534.64','2025-01-03 15:45:48.03295','2025-01-03 15:45:48.03295','football','men'),
	 ('833a80c5-cdab-4be1-8f9c-615e0d595abc','LeBron Witness 8 EP','{"benefits":[{"header":"Max Air made","body":["A Max Air unit in the low-profile midsole is combined with a foam wrap-up for support when you''re moving in lateral directions. It helps cushion your landing while supporting the smooth transition from heel to toe. It also provides side-to-side stability and helps harness and direct your force."]},{"header":"Secure feel","body":["Breathable mesh provides a lightweight, conforming fit in the upper, from the webbing that harnesses your forefoot to the external moulded pieces that help secure your heel. Reinforced stitching along the sides helps the shoe fit snugly for full-foot containment."]},{"header":"Stick and Move","body":["We split the rubber outsole and partially cut it out under the arch to help it bend and flex while helping reduce its overall weight. A classic herringbone pattern adds durable traction."]}],"product_details":[{"header":"Product details","body":["Padded collar","Diamond-stitched quilted tongue","Colour Shown: Light Crimson/Bright Crimson/Gym Red/White","Style: FB2237-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf324a92-3ce0-47ac-be18-193f39f79095/LEBRON+WITNESS+VIII+EP.png','395.29','2025-01-03 15:45:48.033574','2025-01-03 15:45:48.033574','basketball','men'),
