	 ('741aa8c8-69af-4e9d-b517-1b83ebc9e876','Zion 3 PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Black/White/Pear/Light British Tan","Style: DR0676-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/0e7f58b6-1420-4a8c-b80e-ec4fd43506d4/JORDAN+ZION+3+PF.png','748.90','2025-01-03 15:45:48.036776','2025-01-03 15:45:48.036776','basketball','men'),
	 ('81e6a38f-bcbf-4aa4-92dd-729903fb75ea','Tatum 2 PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Blue Void/Leche Blue/Tropical Twist/Bleached Coral","Style: HJ4421-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/30648388-71e0-4cd0-b2b3-72e5c458ec58/JORDAN+TATUM+2+GPX+PF.png','510.20','2025-01-03 15:45:48.037472','2025-01-03 15:45:48.037472','basketball','men'),
	 ('9d4d7065-fec1-487d-b3ba-097de66f5316','Tatum 2 ''Legacy'' PF','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight Build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Black/Wolf Grey/Electric Green","Style: FJ6458-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/3bdf52f5-1615-4bdf-9936-355332055c21/JORDAN+TATUM+2+PF.png','499.24','2025-01-03 15:45:48.038216','2025-01-03 15:45:48.038216','basketball','men'),
	 ('0f507a1f-6ea4-438e-9c6e-10bb0c445234','Jordan One Take 5 PF','{"benefits":[{"header":"Containment for days","body":["The upper, eyestay and wraparound toe piece combine to help give you the on-court containment your game needs."]},{"header":"Up-front response","body":["The Zoom Air unit in the forefoot is top-loaded, bringing the responsive sensation closer to your foot when you''re driving hard down the court."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Embroidered tongue logo","Jumpman on the midsole","Colour Shown: Stone Blue/Mystic Navy/Midnight Navy/Bleached Coral","Style: FD2336-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/939f8560-1646-422b-b271-ec1891e9148e/JORDAN+ONE+TAKE+5+PF.png','707.18','2025-01-03 15:45:48.039619','2025-01-03 15:45:48.039619','basketball','men'),
	 ('5e84871e-f4b9-4ed5-905a-53d0b1f26593','Luka 2 PF','{"benefits":[{"header":"Cushioned for Impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-Step Efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral side wall, complemented by a firm foam carrier and Formula 23 foam in the midsole."]},{"header":"360 Degrees of Support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product Details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Volt/White","Style: DX9012-017","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/f82558ed-76b4-488e-9bf7-06f687478a23/JORDAN+LUKA+2+PF.png','953.84','2025-01-03 15:45:48.040272','2025-01-03 15:45:48.040272','basketball','men'),
	 ('1f5a2390-9ae2-4d2e-9c4c-d2ce1627474f','Nike C1TY','{"benefits":[{"header":"Breathable and durable","body":["With a reinforced rubber side wall and rugged toe box, the breathable upper pairs suede and mesh to keep you cool under pressure."]},{"header":"Secure comfort","body":["Cupsole construction and flexible foam work together to provide round-the-clock comfort and support."]},{"header":"Versatile traction","body":["Dual-stiffness Waffle outsole with rubber lugs delivers supreme grip across all city surfaces."]}],"product_details":[{"header":"Product details","body":["Foam midsole","Rubber outsole","Colour Shown: Black/Stadium Green/Summit White","Style: FZ3863-006","Country/Region of Origin: India"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a00ddf4a-0378-4189-a4fc-09f1a92439aa/NIKE+C1TY.png','705.85','2025-01-03 15:45:48.046886','2025-01-03 15:45:48.046886','lifestyle','men'),
	 ('4bb9526e-91e3-4096-b17a-f7c179520154','LeBron Witness 8 EP','{"benefits":[{"header":"Max Air made","body":["A Max Air unit in the low-profile midsole is combined with a foam wrap-up for support when you''re moving in lateral directions. It helps cushion your landing while supporting the smooth transition from heel to toe. It also provides side-to-side stability and helps harness and direct your force."]},{"header":"Secure feel","body":["Breathable mesh provides a lightweight, conforming fit in the upper, from the webbing that harnesses your forefoot to the external moulded pieces that help secure your heel. Reinforced stitching along the sides helps the shoe fit snugly for full-foot containment."]},{"header":"Stick and Move","body":["We split the rubber outsole and partially cut it out under the arch to help it bend and flex while helping reduce its overall weight. A classic herringbone pattern adds durable traction."]}],"product_details":[{"header":"Product details","body":["Padded collar","Diamond-stitched quilted tongue","Colour Shown: Light Crimson/Bright Crimson/Gym Red/White","Style: FB2237-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf324a92-3ce0-47ac-be18-193f39f79095/LEBRON+WITNESS+VIII+EP.png','656.19','2025-01-03 15:45:48.040992','2025-01-03 15:45:48.040992','basketball','men');
