	 ('ea344af8-1896-4ea2-95b4-f459e598894e','Nike Mercurial Superfly 10 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Dig in, take off","body":["Unique traction pattern offers super-charged traction with quick release to create separation."]},{"header":"Secure fit","body":["You get the same fit from the Superfly 9. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8314-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/82182873-0ecc-4b73-898b-62c1d745e95e/SUPERFLY+10+CLUB+FG%2FMG.png','737.10','2025-01-03 15:45:48.065248','2025-01-03 15:45:48.065248','football','men'),
	 ('acbee937-3128-4712-9003-edf44ee0f7d3','Luka 2 PF','{"benefits":[{"header":"Cushioned for Impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-Step Efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral side wall, complemented by a firm foam carrier and Formula 23 foam in the midsole."]},{"header":"360 Degrees of Support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product Details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: White/Hyper Pink/Black","Style: DX9012-106","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/2ba84c98-37f8-4bb3-96fb-33b72d6b4601/JORDAN+LUKA+2+PF.png','732.65','2025-01-03 15:45:48.052341','2025-01-03 15:45:48.052341','basketball','men'),
	 ('cb8e26a8-d2b4-4dbc-aa93-9594780d3de6','Jordan One Take 5 PF','{"benefits":[{"header":"Containment for days","body":["The upper, eyestay and wraparound toe piece combine to help give you the on-court containment your game needs."]},{"header":"Up-front response","body":["The Zoom Air unit in the forefoot is top-loaded, bringing the responsive sensation closer to your foot when you''re driving hard down the court."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Embroidered tongue logo","Jumpman on the midsole","Colour Shown: Stone Blue/Mystic Navy/Midnight Navy/Bleached Coral","Style: FD2336-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/939f8560-1646-422b-b271-ec1891e9148e/JORDAN+ONE+TAKE+5+PF.png','756.82','2025-01-03 15:45:48.052983','2025-01-03 15:45:48.052983','basketball','men'),
	 ('196c7627-b173-4697-9bf9-77dba71d5a7b','Luka 2 PF','{"benefits":[{"header":"Cushioned for Impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-Step Efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral side wall, complemented by a firm foam carrier and Formula 23 foam in the midsole."]},{"header":"360 Degrees of Support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product Details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Volt/White","Style: DX9012-017","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/f82558ed-76b4-488e-9bf7-06f687478a23/JORDAN+LUKA+2+PF.png','897.87','2025-01-03 15:45:48.054291','2025-01-03 15:45:48.054291','basketball','men'),
	 ('cc8824fa-1cf4-4cfd-b799-3b25fc57f268','LeBron Witness 8 EP','{"benefits":[{"header":"Max Air made","body":["A Max Air unit in the low-profile midsole is combined with a foam wrap-up for support when you''re moving in lateral directions. It helps cushion your landing while supporting the smooth transition from heel to toe. It also provides side-to-side stability and helps harness and direct your force."]},{"header":"Secure feel","body":["Breathable mesh provides a lightweight, conforming fit in the upper, from the webbing that harnesses your forefoot to the external moulded pieces that help secure your heel. Reinforced stitching along the sides helps the shoe fit snugly for full-foot containment."]},{"header":"Stick and Move","body":["We split the rubber outsole and partially cut it out under the arch to help it bend and flex while helping reduce its overall weight. A classic herringbone pattern adds durable traction."]}],"product_details":[{"header":"Product details","body":["Padded collar","Diamond-stitched quilted tongue","Colour Shown: Light Crimson/Bright Crimson/Gym Red/White","Style: FB2237-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf324a92-3ce0-47ac-be18-193f39f79095/LEBRON+WITNESS+VIII+EP.png','985.06','2025-01-03 15:45:48.055043','2025-01-03 15:45:48.055043','basketball','men'),
	 ('647248ba-5db2-40d7-867e-e17aea1780e0','Nike Air Max Pulse SE','{"benefits":[{"header":"New sensation","body":["We''ve point-loaded the Air unit with a plastic clip, meaning more Air is utilised with every step to deliver an elevated experience full of bounce."]},{"header":"This ain''t a gym shoe","body":["They may feel like your comfiest gym shoes, but the design is all lifestyle. Throw them on with your best outfit and hit the streets."]}],"product_details":[{"header":"Product details","body":["Foam midsole","Rubber Waffle outsole","Not intended for use as personal protective equipment (PPE)","Colour Shown: Summit White/Phantom/Summit White/Phantom","Style: FN6919-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/4f7eb45f-739f-4099-b0d9-c69a24aef88a/NIKE+AIR+MAX+PULSE+SE.png','464.45','2025-01-03 15:45:48.106735','2025-01-03 15:45:48.106735','lifestyle','men'),
	 ('fa5a8236-93d2-4164-adc2-3e154445f999','Tatum 2 PF ''Red Cement''','{"benefits":[{"header":"Contoured fit","body":["The frame wraps underneath the sole and onto the upper, helping support your low-to-the-ground gameplay."]},{"header":"Get grippy","body":["You''re always moving on the court. That''s where the rubber outsole and ground-contact foam come in—adding responsiveness and traction for your offence and defence."]},{"header":"Lightweight build","body":["Every time you go up with a light shoe, you''re saving energy. We used rubber on the outsole (where you need it most) but foam with ample traction does the heavy lifting."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: White/Bright Crimson/Black","Style: FJ6458-106","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/64e58613-39ba-4e9e-b9aa-0ba0cd15d847/JORDAN+TATUM+2+PF.png','483.07','2025-01-03 15:45:48.056594','2025-01-03 15:45:48.056594','basketball','men'),
	 ('51523978-63ca-4d00-8ee1-7bfa01db58ab','Zion 3 PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Black/White/Pear/Light British Tan","Style: DR0676-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/0e7f58b6-1420-4a8c-b80e-ec4fd43506d4/JORDAN+ZION+3+PF.png','440.21','2025-01-03 15:45:48.058017','2025-01-03 15:45:48.058017','basketball','men'),
	 ('5bb12963-b93a-4485-b547-21819d2ca2aa','Luka 2 PF','{"benefits":[{"header":"Cushioned for Impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-Step Efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral side wall, complemented by a firm foam carrier and Formula 23 foam in the midsole."]},{"header":"360 Degrees of Support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product Details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Bright Mango/Black/Barely Green","Style: DX9012-800","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/4b8d3b6c-e5cf-4c19-8d89-4e05dad6ebf9/JORDAN+LUKA+2+PF.png','785.44','2025-01-03 15:45:48.058677','2025-01-03 15:45:48.058677','basketball','men'),
	 ('59accf63-12d1-4a8e-a9d4-9861d01e1ca0','Luka 2 PF','{"benefits":[{"header":"Cushioned for impact","body":["When you''re shifting side to side, you need support that''s firm—but not rigid. A wedge of cushioning in the midsole butts up against the medial sidewall so you can bank like a champ, and a thick, moulded insole helps you stay grounded."]},{"header":"Last-step efficiency","body":["The other aspect of side-to-side movement? Lateral support. To help your quick stops feel secure, we added a strong, flexible plate that runs up the lateral sidewall, complemented by a firm foam carrier in the midsole."]},{"header":"360 degrees of support","body":["A sturdy cage wraps around the entire upper for 360-degree connected support that help your feet stay securely contained, whichever way you step—or however quick you stop."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Olive Aura/Oil Green/Sea Glass/Vivid Orange","Style: DX9034-308","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7a332de6-e409-4ab0-a4b1-882d3bc3808a/JORDAN+LUKA+2+S+PF.png','711.87','2025-01-03 15:45:48.060669','2025-01-03 15:45:48.060669','basketball','men');
