	 ('abb03de0-dc57-449d-9e4a-fdfe51e11a6a','Zion 3 M.U.D. ''Ash'' SE PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Colour Shown: Black/Sail/Dark Ash","Style: FN1778-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/8757bda7-3ab6-44ae-8645-974099dcf963/JORDAN+ZION+3+SE+PF.png','720.17','2025-01-03 15:45:48.061315','2025-01-03 15:45:48.061315','basketball','men'),
	 ('a0b57674-c92b-4ac2-b3c3-6c1e6b17b893','Zion 3 M.U.D. "Light Bone" PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Light Bone/Sail/Volt/Light Bone","Style: FN1778-040","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/56a05251-b96e-4e2f-97cf-e77c33ddef4c/JORDAN+ZION+3+SE+PF.png','938.12','2025-01-03 15:45:48.061948','2025-01-03 15:45:48.061948','basketball','men'),
	 ('c745413c-51b8-4e4c-ba61-92c3d0c2ab4c','Nike Vomero 17 ''Talaria''','{"benefits":[{"header":"Behind the design","body":["This unique Vomero 17 takes its design cues from the famed ''Tennis Ball'' edition, one that took the running world by storm thanks to its sleek, aggressive build and iconic Volt hits."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 298g (men''s size 9)","Heel-to-toe drop: 10mm","MR-10 Last—Our best, most consistent fit","Not intended for use as personal protective equipment (PPE)","Colour Shown: Volt/White/Bright Crimson/Black","Style: FZ8587-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/230b8e64-8eb0-4568-aaed-d0142f97dc70/NIKE+VOMERO+17+TALARIA.png','307.31','2025-01-03 15:45:48.062637','2025-01-03 15:45:48.062637','running','men'),
	 ('4cbc7a0f-24a5-48e9-b73a-de2e8e36cad9','Zion 3 ''Z-3D'' PF','{"benefits":[{"header":"Lateral action","body":["Side to side, left to right. Traction on the outsole helps you grip the court with every step, while a foam carrier in the midsole adds support for your ankle and heel."]},{"header":"Up fast, down hard","body":["Nike Air helps you get those powerful ups when you blast off the court—and adds cushioning on re-entry."]},{"header":"Get low","body":["For improved ground feel, we dropped in some Formula 23 foam. It''s soft and responsive underfoot, helping you stay low in your movements."]}],"product_details":[{"header":"Product details","body":["PF edition is designed to fit wide for play on outdoor courts.","Colour Shown: Football Grey/Flash Crimson/Chlorine Blue/Black","Style: FZ1319-060","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/519973a6-a890-4e1e-b46a-d5b3ce2db905/JORDAN+ZION+3+NRG+PF.png','798.50','2025-01-03 15:45:48.063256','2025-01-03 15:45:48.063256','basketball','men'),
	 ('aefda911-cbbb-42cd-90d3-48687c38f7a7','Nike Mercurial Vapor 16 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Dig in, take off","body":["Unique traction pattern offers super-charged traction with quick release to create separation."]},{"header":"Secure fit","body":["You get the same fit from the Vapor 15. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8441-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/05442d82-fde1-401f-a24e-33409f65c375/VAPOR+16+CLUB+FG%2FMG.png','875.30','2025-01-03 15:45:48.063885','2025-01-03 15:45:48.063885','football','men'),
	 ('247fa907-e118-4587-9176-0c4d94f037ee','Nike Phantom GX 2 Academy EasyOn Electric','{"benefits":[{"header":"FlyEase is now EasyOn","body":["As we continue to make more Nike products easier to wear and use for every body, we switched up the name to make it easier to understand. A shaped heel counter makes it easy put the boot on. A hook-and-loop strap with flexible webbing offers adjustability across the boot. Plus, braille on the heel helps you tell the difference between the left and right boots."]},{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The newly implemented blend of conical and tri-star studs help unlock change of direction and movement for an easy transition, allowing you to tack down into the grass for a quick take-off."]},{"header":"Comfortable fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned Insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8199-900","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/cb278f08-a4ad-43b8-824a-641196ddaf4c/PHANTOM+GX+II+ACAD+EASE+FGMG.png','804.32','2025-01-03 15:45:48.065875','2025-01-03 15:45:48.065875','football','men'),
	 ('24e62ff4-eb76-439d-b763-3d64110ff7c3','Nike React Phantom Run Flyknit 2','{"benefits":[{"header":"Secure Feel","body":["The latest in Flywire technology features an elastic design that intertwines with the Flyknit upper, helping your foot feel secure as you run."]},{"header":"Lightweight and Breathable","body":["Flyknit Loft uses 3 forefoot layers.They combine for a lightweight, breathable and durable feel that keeps your foot comfortable."]},{"header":"Smooth and Responsive","body":["Nike React technology delivers a soft, responsive ride.It provides support for the 3 phases of a runner''s stride—flexibility at toe-off, a smooth ride at mid-stance and cushioning at contact."]}],"product_details":[{"header":"Product Details","body":["Synthetic leather and textile materials in the upper","Offset: 10mm (Forefoot: 18.5mm, Heel: 28.5mm)","Colour Shown: Iron Grey/Black/Particle Grey/Metallic Silver","Style: CJ0277-006","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/4236bee2-d8e8-448d-859b-77a57197eb6a/NIKE+REACT+PHANTOM+RUN+FK+2.png','519.23','2025-01-03 15:45:48.111769','2025-01-03 15:45:48.111769','running','men'),
	 ('3fda16ac-6786-43da-959f-aa092f2fa304','Nike Tiempo Legend 10 Elite','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4328-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a1a9a3a2-deac-4569-acd4-f3ae09b572df/LEGEND+10+ELITE+FG.png','889.11','2025-01-03 15:45:48.066684','2025-01-03 15:45:48.066684','football','men'),
	 ('3d46c47b-d0e4-49bb-beee-5cafbcfcfd3a','Nike Mercurial Vapor 16 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Reliable traction","body":["Rubber outsole is designed for traction on turf surfaces."]},{"header":"Secure fit","body":["You get the same fit from the Vapor 15. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ8446-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/330b8b63-9bb6-4399-9c7c-1d68bfdcfdd3/VAPOR+16+CLUB+TF.png','303.25','2025-01-03 15:45:48.067334','2025-01-03 15:45:48.067334','football','men'),
	 ('3bcfdec1-8c24-40c4-b0d1-40f6d8028308','Nike Mercurial Vapor 16 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8374-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2f196101-347d-4bf5-a86a-a816577eda22/ZOOM+VAPOR+16+ACADEMY+FG%2FMG.png','940.95','2025-01-03 15:45:48.068004','2025-01-03 15:45:48.068004','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('07ff0df6-d40f-4e54-851f-ed6917754249','Nike Phantom GX 2 Club','{"benefits":[{"header":"Grippy touch","body":["A grippy texture covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Reliable Traction","body":["The outsole plate has a broken-in feel to help you play fast from the first time you put these on."]},{"header":"Comfortable Fit","body":["Synthetic leather on the upper helps keep you comfortable on the pitch."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FJ2557-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a3ab8d17-8664-453b-8cfa-afa178155587/PHANTOM+GX+II+CLUB+FG%2FMG.png','890.62','2025-01-03 15:45:48.069559','2025-01-03 15:45:48.069559','football','men'),
	 ('1182150e-428f-41e4-ad0c-7480037dbcdc','Nike Phantom GX 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the shoe, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Comfortable Fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FJ2577-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/62e3d9c1-0d94-4f95-b948-854d25549650/PHANTOM+GX+II+ACADEMY+TF.png','887.66','2025-01-03 15:45:48.070235','2025-01-03 15:45:48.070235','football','men'),
	 ('c5bbb5c9-0893-45bd-8f72-9e8dc2f2ff0f','Nike Phantom GX 2 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8003-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/22e2ecb5-63c9-474a-bc59-81c999a26d87/PHANTOM+GX+II+ELITE+FG.png','854.00','2025-01-03 15:45:48.071125','2025-01-03 15:45:48.071125','football','men'),
	 ('25fa1fb5-2306-42f9-8c93-f9392245a4f0','Nike Tiempo Legend 10 Elite','{"benefits":[{"header":"Brilliant Swoosh design","body":["Designed with the hard work of brilliance in mind, the textured Swoosh logo symbolises the friction that goes into polishing a gem before it shines. The Grey resembles the darkness you work under while the plate has an iridescent finish that represents your breakthrough moment when it''s time to shine. A gleaming upper along the side of the heel represents the shining light that breaks through the darkness."]},{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Not intended for use as personal protective equipment (PPE)","Cushioned insole","Colour Shown: Atmosphere Grey/Black","Style: FQ3250-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a8a13a14-c61c-4d1c-8ee2-756af9a36128/LEGEND+10+ELITE+FG+AS.png','684.78','2025-01-03 15:45:48.071881','2025-01-03 15:45:48.071881','football','men'),
	 ('df61d094-08d7-4796-9bbe-00e272dad23c','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: Black/Wolf Grey/Cool Grey/White","Style: DD9304-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/02908fb5-b54c-471f-b053-e3a6e306d7f4/NIKE+RENEW+ELEVATE+III.png','457.95','2025-01-03 15:45:48.132303','2025-01-03 15:45:48.132303','basketball','women'),
	 ('090f88b5-ad6c-4f7e-9231-9f5e7dbeed26','Nike Phantom GX 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the pinky toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Comfortable Fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FD6723-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c8d83936-f960-4d5f-be6f-9105c84a1fa0/PHANTOM+GX+II+ACADEMY+FG%2FMG.png','355.23','2025-01-03 15:45:48.073381','2025-01-03 15:45:48.073381','football','men'),
	 ('4d2a0e17-9108-438d-aa6b-fa95416bbf3c','Nike Mercurial Vapor 16 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["A rubber outsole gives you traction for turf surfaces."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ8449-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/93ca7a3c-9f8c-4278-bb3e-97fd11e3dd40/ZOOM+VAPOR+16+ACADEMY+TF.png','755.02','2025-01-03 15:45:48.074146','2025-01-03 15:45:48.074146','football','men'),
	 ('e0de847e-53fd-4bd4-bb37-063c83309639','Nike Phantom Luna 2 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. The asymmetrical Flyknit cuff material provides snugness and shape around your ankle. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Sunset Pulse/Black","Style: FJ2572-600","Country/Region of Origin: Bosnia \u0026 Herzegovina"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f03bbe0f-9863-417e-a7db-085f7f844b82/PHANTOM+LUNA+II+ELITE+FG.png','433.08','2025-01-03 15:45:48.075852','2025-01-03 15:45:48.075852','football','men'),
	 ('364dd936-5b09-4ca3-879e-06800a9b42df','Nike Phantom Luna 2 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. The asymmetrical Flyknit cuff material provides snugness and shape around your ankle. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8002-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/641c2ad1-800d-469a-9b5b-55b69ec6be60/PHANTOM+LUNA+II+ELITE+FG.png','721.71','2025-01-03 15:45:48.078128','2025-01-03 15:45:48.078128','football','men'),
	 ('41cfa01b-3eac-482f-8339-0d246093bf1f','Nike Phantom Luna 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the pinky toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Fit for the pitch","body":["The anatomical mesh cuff offers soft comfort around your ankle and heel. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FD6725-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/eabbcad7-b3af-44e4-ae91-40da9d7b297e/PHANTOM+LUNA+II+ACADEMY+FG%2FMG.png','469.79','2025-01-03 15:45:48.078849','2025-01-03 15:45:48.078849','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('a8c101d0-4077-4397-b066-da9e15b7524b','Nike Phantom GX 2 Elite','{"benefits":[{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FJ2559-002","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3873d1b3-d130-4fcd-b0e7-b607d0cc7287/PHANTOM+GX+II+ELITE+FG.png','606.57','2025-01-03 15:45:48.080355','2025-01-03 15:45:48.080355','football','men'),
	 ('d79505d2-bc5f-4a30-9c9e-2e2df6f0d87f','Nike Vapor 16 Academy Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1388-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/01ef5c55-1991-46f5-b261-7812c92b432a/ZM+VAPOR+16+ACADEMY+MDS+FG%2FMG.png','471.70','2025-01-03 15:45:48.083557','2025-01-03 15:45:48.083557','football','men'),
	 ('3899ce48-0b72-4344-87f5-1127d79f5e67','Nike Air Max Excee','{"benefits":[{"header":"Visible Air","body":["The Air-Sole unit is visible through 3 windows for an updated look."]},{"header":"Lightweight Comfort","body":["The foam midsole and outsole provide comfort without weighing you down."]},{"header":"Modern Look","body":["Elongated design lines honour the Air Max 90 while modernising it in a provocative way."]}],"product_details":[{"header":"Product Details","body":["Mesh, leather and suede upper with synthetic leather overlays","Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: White/Astronomy Blue/Wolf Grey/Black","Style: CD4165-120","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2e998fd3-25c2-418f-a3a9-88dbc901a1a9/NIKE+AIR+MAX+EXCEE.png','844.70','2025-01-03 15:45:48.085009','2025-01-03 15:45:48.085009','lifestyle','men'),
	 ('0b65f244-e3b7-43a2-b80d-29cfd780f089','Nike Air Max Dn Premium Electric','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Colour Shown: Multi-Colour/Multi-Colour","Style: HM0811-900","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf6dcf4d-8306-4a51-abf6-2ffc4649ae6a/AIR+MAX+DN+SE+PRM.png','595.04','2025-01-03 15:45:48.086126','2025-01-03 15:45:48.086126','lifestyle','men'),
	 ('e9e954f7-5df5-4d0a-997b-16b1fb0f805a','Nike Phantom GX 2 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on longer, artificial-grass surfaces","Cushioned insole","Colour Shown: Metallic Silver/Volt/Black","Style: FJ2554-003","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ee409eb2-398a-42f5-9698-826b5c936aa2/PHANTOM+GX+II+ELITE+AG-PRO.png','479.95','2025-01-03 15:45:48.087691','2025-01-03 15:45:48.087691','football','men'),
	 ('d9ca1a30-98e5-4817-bf77-c5ec2a27b181','Nike Mercurial Superfly 10 Academy ''Kylian Mbappé''','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Light Laser Orange/Armoury Navy","Style: FQ8293-800","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bcaf1d52-6ec4-4acb-a7a5-48a685aac77f/ZM+SUPERFLY+10+ACAD+KM+FG%2FMG.png','414.03','2025-01-03 15:45:48.088541','2025-01-03 15:45:48.088541','football','men'),
	 ('49a70988-0889-40dc-bdb7-7dc4ffd709c5','Nike Mercurial Superfly 10 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Reliable traction","body":["Rubber outsole is designed for traction on turf surfaces."]},{"header":"Secure fit","body":["You get the same fit from the Superfly 9. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel. Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8317-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/52658141-66f5-4cba-85da-c8caf82cfdf1/SUPERFLY+10+CLUB+TF.png','680.58','2025-01-03 15:45:48.089446','2025-01-03 15:45:48.089446','football','men'),
	 ('18c36fe4-603c-45f1-bca2-b9d7d3440936','Nike Mercurial Vapor 15 Academy','{"benefits":[{"header":"Welcome to the pitch, Zoom","body":["For the 1st time in our history, Nike has developed an all-new Zoom Air unit. It sits in the outsole and provides an additional level of springy underfoot feel that helps you move faster on the pitch and create separation when it matters the most—whether you''re scoring goals, being first to the ball or going past defenders."]},{"header":"Drive your speed","body":["The speed cage inside the structure is made from a thin but strong material that secures the foot to the outsole without adding additional weight for optimal lockdown."]},{"header":"Dig in, take off","body":["Rubber outsole is designed for traction on turf surfaces."]},{"header":"Improved fit","body":["A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and better lockdown in the heel."]},{"header":"Feel the ball","body":["The upper has NikeSkin, a soft and flexible mesh material linked together by a thin coating. It helps provide ball control and truly gives you a feeling of barefoot football."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Lemonade/Black","Style: DJ5635-700","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/81c121db-746a-48b3-82c4-1e3811a9c015/ZOOM+VAPOR+15+ACADEMY+TF.png','846.18','2025-01-03 15:45:48.091743','2025-01-03 15:45:48.091743','football','men'),
	 ('ac742365-10fe-4208-9f4b-d8f10397ebba','Nike Air Max Excee','{"benefits":[{"header":"Visible Air","body":["The Air unit is visible through 3 windows, for an updated look."]},{"header":"Lightweight Comfort","body":["A foam midsole and foam and rubber outsole pods provide lightweight comfort and durability."]},{"header":"Modern Touch","body":["Elongated design lines honour the Air Max 90 while modernising it in a provocative way."]}],"product_details":[{"header":"Product Details","body":["Mesh, leather and synthetic upper with overlays","Colour Shown: Sail/Lilac Bloom/Medium Soft Pink/Summit White","Style: CD5432-130","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6d16ab3a-72db-4a67-9820-95f240e552e2/WMNS+NIKE+AIR+MAX+EXCEE.png','993.25','2025-01-03 15:45:48.093138','2025-01-03 15:45:48.093138','lifestyle','women'),
	 ('c4d9ebb1-e0a8-47c0-b855-f4c34b0cf56a','Nike React Gato','{"benefits":[{"header":"Nike Touch 360","body":["Flexible rubber pods underfoot reach just below the sole for improved touch and tactile responsiveness. Awareness of the ball is heightened as the pods extend up slightly under the cushioning into the sole of your foot."]},{"header":"Responsive Cushioning","body":["Full-length Nike React cushioning has incredible energy return to keep you moving."]},{"header":"Precise, Durable Touch","body":["Flyknit is fused with a durable compound and moulded to provide a precise touch at high-speeds. A reinforced band around the toe adds durability."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Cushioned insole","Colour Shown: University Red/University Red","Style: CT0550-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9ab09ff0-b728-4d9c-add8-c18541dcd8da/NIKE+REACTGATO.png','728.34','2025-01-03 15:45:48.09385','2025-01-03 15:45:48.09385','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('724ee228-cf01-4aab-a100-a9a79c8bb00c','Nike Tiempo Emerald Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. The tongue construction with additional padding gives you a secure feel and comfort in key areas. Microfibre lining creates a premium feel."]},{"header":"Traction for the Turf","body":["A rubber outsole gives you traction on turf surfaces."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Dark Atomic Teal/Sail","Style: FQ3245-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ab88b180-988e-4701-ae7c-8cdee123e7a6/LEGEND+10+ACADEMY+TF+30.png','398.24','2025-01-03 15:45:48.095339','2025-01-03 15:45:48.095339','football','men'),
	 ('535faf7a-7793-4b42-bc63-5977e7028612','Nike Air VaporMax 2023 Flyknit','{"benefits":[{"header":"Lighter Than Air","body":["You''ll be walking on Air and feeling lighter than it—this shoe weighs less than any other model with this Air unit so far."]},{"header":"Flying High","body":["Stretchy and supportive Flyknit upper creates a striking visual that''s seamless, breathable and feels as light as air."]}],"product_details":[{"header":"Product Details","body":["Rubber outsole","Traditional lacing","Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: Anthracite/Black/Anthracite/Black","Style: DV1678-006","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/fab8b8d1-3bac-48f9-9533-2bdc561bcd4b/AIR+VAPORMAX+2023+FK.png','847.67','2025-01-03 15:45:48.096837','2025-01-03 15:45:48.096837','lifestyle','men'),
	 ('9320b46c-da0d-4493-b97f-37378636bd56','Nike Air Max Pulse','{"benefits":[{"header":"Unreal Sensation","body":["A new point-loaded cushioning system features a plastic clip that distributes weight to targeted points across the Air unit, delivering a unique experience full of bounce."]},{"header":"All Day, All Night","body":["Performance comfort re-engineered for the streets, the sporty design is eye-catching and versatile. Throw them on with your best outfit and go to the max."]}],"product_details":[{"header":"Product Details","body":["Textile upper","Leather and synthetic overlays","Foam midsole","Rubber Waffle outsole","Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: Light Iron Ore/Phantom/Sail/Baroque Brown","Style: FD6409-005","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a4c35b29-fa33-492c-82be-0c6bdb56184b/W+NIKE+AIR+MAX+PULSE.png','647.54','2025-01-03 15:45:48.203065','2025-01-03 15:45:48.203065','lifestyle','women'),
	 ('9375c9f5-f5bf-40b7-9194-7b9a6b27fbae','Nike Air Max Dn SE','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the gradient upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Foam midsole","Rubber outsole","Colour Shown: Sky Blue/Hyper Blue/Black/Chamois","Style: HM0810-401","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/aa6ab83d-e49a-4ee8-8368-8c3b16b65a1e/AIR+MAX+DN+SE.png','782.31','2025-01-03 15:45:48.098333','2025-01-03 15:45:48.098333','lifestyle','men'),
	 ('a2468ad1-ebb3-4123-a8d1-526940f2bc21','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Glossy accents","Foam midsole","Rubber outsole","Colour Shown: Black/Black/Metallic Dark Grey/Black","Style: FJ3145-003","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b768ac95-eca6-4948-83d8-d34efce41ba5/W+AIR+MAX+DN.png','799.27','2025-01-03 15:45:48.099849','2025-01-03 15:45:48.099849','lifestyle','men'),
	 ('79532311-e2a9-4c4a-b164-2c81f9a48d36','Nike Air Max 90','{"benefits":[{"header":"Performance Comfort","body":["Originally designed for performance running, the Max Air unit in the heel adds unbelievable cushioning."]},{"header":"Versatile Style","body":["The low-top design combines with a padded collar for a sleek look that feels soft and comfortable."]},{"header":"Retro Vibes","body":["The stitched overlays and TPU accents add durability, comfort and the iconic ''90s look you love."]}],"product_details":[{"header":"Product Details","body":["Textile upper with leather and synthetic overlays","Foam midsole","Rubber Waffle outsole adds traction and durability","Colour Shown: Iron Grey/Dark Smoke Grey/Black/White","Style: CN8490-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/w2ldynwtyuspv6r5rffj/AIR+MAX+90.png','800.93','2025-01-03 15:45:48.100548','2025-01-03 15:45:48.100548','lifestyle','men'),
	 ('2a68e1aa-4ef1-4a9a-b80a-8092aad6bc92','Nike Terrascout','{"benefits":[{"header":"Step into exploration","body":["Rubber outsole with rugged tread pattern helps provide durable traction. Flex grooves in the outsole add flexibility, helping every step feel natural."]},{"header":"Easy to pull on","body":["Lowered back collar works with pull tabs on the tongue and heel to help make these easy to pull on."]},{"header":"Warm and cosy details","body":["Quilted fabric around the collar pairs with a soft fleece lining to help keep your feet warm in cold weather."]}],"product_details":[{"header":"Product details","body":["Classic laces","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Hemp/Burgundy Ash/Denim Turquoise/Pale Ivory","Style: FV4173-200","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/aed680ec-8d69-4d01-b354-eb9273a6cbd0/NIKE+TERRASCOUT+%28GS%29.png','858.77','2025-01-03 15:45:48.103045','2025-01-03 15:45:48.103045','lifestyle','men'),
	 ('20685399-26cf-416d-a893-28eb6e5458d2','Nike Terrascout','{"benefits":[{"header":"Step into exploration","body":["Rubber outsole with rugged tread pattern helps provide durable traction. Flex grooves in the outsole add flexibility, helping every step feel natural."]},{"header":"Easy to pull on","body":["Lowered back collar works with pull tabs on the tongue and heel to help make these easy to pull on."]},{"header":"Warm and cosy details","body":["Quilted fabric around the collar pairs with a soft fleece lining to help keep your feet warm in cold weather."]}],"product_details":[{"header":"Product details","body":["Classic laces","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Hemp/Burgundy Ash/Denim Turquoise/Pale Ivory","Style: FV4173-200","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/aed680ec-8d69-4d01-b354-eb9273a6cbd0/NIKE+TERRASCOUT+%28GS%29.png','838.40','2025-01-03 15:45:48.103745','2025-01-03 15:45:48.103745','lifestyle','men'),
	 ('225d18a7-3835-429a-aec4-0220d31ec4e3','Nike Air Max Dn','{"benefits":[{"header":"Maxxed Out motion","body":["Our Dynamic Air unit system features 2 sets of dual-pressure tubes. With the firmest amount of pressure in the heel and the softest amount of pressure towards your midfoot, the air levels shift within each set for a smooth transition as you step."]},{"header":"Maxxed Out comfort","body":["The multi-layered mesh on the upper feels lightweight and breathable, with a haptic print for a textured look. Plush foam surrounds the cushioning system for an enhanced feel that''s uniquely soft and supportive."]},{"header":"Maxxed Out energy","body":["Providing comfort from top to bottom, this tactile design boasts performance-level bounce to energise your every move. After all, who said going to a concert isn''t a sport?"]}],"product_details":[{"header":"Product details","body":["Matt accents","Foam midsole","Rubber outsole","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Light Orewood Brown/Black/Denim Turquoise/Light Orewood Brown","Style: HQ3478-104","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d0532950-2f8d-4f33-8166-4eb83a68e93b/AIR+MAX+DN.png','542.35','2025-01-03 15:45:48.105171','2025-01-03 15:45:48.105171','lifestyle','men'),
	 ('e52f0d38-b700-47c1-99b7-b7ace385d3c8','Nike Air Max Pulse','{"benefits":[{"header":"Unreal Sensation","body":["A new point-loaded cushioning system features a plastic clip that distributes weight to targeted points across the Air unit, delivering a unique experience full of bounce."]},{"header":"All Day, All Night","body":["Performance comfort re-engineered for the streets, the sporty design is eye-catching and versatile. Throw them on with your best outfit and go to the max."]}],"product_details":[{"header":"Product Details","body":["Textile on the upper","Leather and synthetic overlays","Foam midsole","Rubber Waffle outsole","Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: White/Summit White/White","Style: DR0453-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d858287a-d718-482e-804b-3bff435113d5/NIKE+AIR+MAX+PULSE.png','367.80','2025-01-03 15:45:48.105888','2025-01-03 15:45:48.105888','lifestyle','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('d1a98e7c-6f50-4a68-8de4-7d267b531e25','Nike Alphafly 3 Premium','{"benefits":[{"header":"Fuel the fire","body":["This edition draws colour inspiration from the Japanese flag, ready to usher in the next centennial of this New Year''s relay race."]},{"header":"Energy return for the ekiden","body":["Two forefoot Air Zoom units combine with ZoomX foam to store and return the energy back to you, powering every step."]},{"header":"Fire underfoot","body":["A full-length carbon-fibre plate delivers a propulsive sensation that helps you smoothly transition through every stride and tackle turns with confidence."]},{"header":"What''s new about the Alphafly 3?","body":["The Alphafly 3 is our lightest Alphafly ever, featuring a slightly wider carbon-fibre plate for increased stability, a fully connected ZoomX foam midsole for smoother transitions and an all-new AtomKnit upper designed for improved multi-directional containment and breathability."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 218g (men''s size 9)","Heel-to-toe drop: 8mm","Colour Shown: White/Black/University Red/Habanero Red","Style: HQ3501-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b98e67b8-45cf-4bfa-81f8-c1f3ea6461de/AIR+ZOOM+ALPHAFLY+NEXT%25+3+PRM.png','680.98','2025-01-03 15:45:48.107443','2025-01-03 15:45:48.107443','running','men'),
	 ('c5f1fb58-db0d-4714-92d4-ca33efd2bd01','Nike Zoom Fly 6 ''Eliud Kipchoge''','{"benefits":[{"header":"Keep growing","body":["Whenever someone trains with Eliud Kipchoge, they''re asked to plant a tree at his base camp to signify their growth. The sockliner graphics mimic that growth with branches moving forwards towards the front of the shoe. The Red Clay colour fade nods to the Kenyan dirt that stains the shoes when training. The font is a play on African trees that have fractal-like patterns on the surfaces."]}],"product_details":[{"header":"Product details","body":["Weight: 265g approx. (men''s UK 9)","Heel-to-toe drop: 8mm","Synthetic leather on upper","Not intended for use as personal protective equipment (PPE)","Colour Shown: White/Pale Ivory/Sail/Black","Style: HJ7038-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/951d61fb-6bec-478e-935a-825bcc181795/ZOOM+FLY+6+EK.png','715.76','2025-01-03 15:45:48.109664','2025-01-03 15:45:48.109664','running','men'),
	 ('fa94960e-d0a9-4c05-bd08-2c34c0279dad','Nike Downshifter 13','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole is made from at least 15% Nike Grind material, derived from scraps from the footwear-manufacturing process."]},{"header":"Breathable mesh","body":["Soft and comfortable mesh offers a high level of breathability."]},{"header":"Supportive and secure","body":["An updated internal fit band offers containment around the midfoot for support and security."]}],"product_details":[{"header":"Product details","body":["Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Photon Dust/Phantom/Summit White/Light Smoke Grey","Style: FD6454-008","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/897e783a-0712-48fe-8bf7-1ef56e2466ce/NIKE+DOWNSHIFTER+13.png','505.26','2025-01-03 15:45:48.110361','2025-01-03 15:45:48.110361','running','men'),
	 ('eb0568df-cfb9-47d9-9c0b-e1ec04c26696','Nike Juniper Trail 3','{"benefits":[{"header":"All-terrain ready","body":["The Nike Trail ATC outsole is made from an all-terrain compound that''s great even in wet weather. It provides grip on any surface while maintaining durability and a smooth ride on the road."]},{"header":"Smooth Ride","body":["The full-length foam midsole provides a soft and cushioned ride. A flexible midfoot system connects the upper and the midsole for increased support and stability."]},{"header":"Soft touch","body":["We softened the touch points along the collar foam and tongue to help minimise distractions."]},{"header":"Comfort and Containment","body":["Durable mesh provides comfort and containment."]}],"product_details":[{"header":"Product details","body":["Weight: 323 grams approx. (men''s UK 9)","Heel-to-toe drop: 10mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Sequoia/College Grey/White Onyx/Summit White","Style: FQ0904-301","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a996f266-8cec-474e-abca-f4eb2aae4991/NIKE+JUNIPER+TRAIL+3.png','939.59','2025-01-03 15:45:48.111066','2025-01-03 15:45:48.111066','running','men'),
	 ('a1eba6dc-bb2e-407b-9e88-9b33aa458d8b','Nike Vaporfly 3','{"benefits":[{"header":"Propelling you forwards","body":["A full-length carbon fibre flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ride","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft, yet supportive yarns deliver our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 200g (men''s size 9)","Heel-to-toe drop: 8mm","Wider toe area for a roomier fit","Internal foam pod on the heel for extra cushioning","Colour Shown: Volt/Scream Green/Barely Volt/Black","Style: DV4129-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9fe70154-e4bb-4bcc-9cf0-2efda240916c/NIKE+ZOOMX+VAPORFLY+NEXT%25+3.png','609.95','2025-01-03 15:45:48.112535','2025-01-03 15:45:48.112535','running','men'),
	 ('d57c5790-a238-413e-aa11-69f531c81eee','Nike Zegama Trail 2','{"benefits":[{"header":"Stay sticky","body":["Vibram Zegama outsole made with Vibram Megagrip has a diverse lug pattern highlighted with wide spacing. This means you get traction for more technical terrains."]},{"header":"Keep running","body":["A lightweight Nike ZoomX midsole is combined with increased stack heights to help provide cushioning during extended stretches of running."]},{"header":"Stable for trails","body":["Engineered mesh—stronger and more flexible than normal mesh—on the upper helps provide stability for various trail conditions."]}],"product_details":[{"header":"Product details","body":["Weight: 320 grams approx. (men''s UK 9)","Heel-to-toe drop: 4mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Off-Noir/Monarch/Pale Ivory/Black","Style: FD5190-008","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/69a39e90-4408-4b40-ae49-f877548db239/NIKE+ZOOMX+ZEGAMA+TRAIL+2.png','793.17','2025-01-03 15:45:48.114092','2025-01-03 15:45:48.114092','running','men'),
	 ('5fdfe75a-7b7c-47fa-87ef-126e6092d1d6','Nike Interact Run','{"benefits":[{"header":"To the future","body":["A scannable QR code on the tongue acts as your tour guide to the Interact Run''s performance benefits. It offers tips on how to extend the life cycle of your shoe from upkeep options to repairs and long-term care. Finally, when you''ve logged all the miles you can, the QR code will suggest ways to recycle and donate the shoes once they''ve run their course."]},{"header":"Made from Nike Grind","body":["The Waffle outsole is made from at least 13% Nike Grind material, crafted from scraps from the footwear-manufacturing process."]},{"header":"Soft ride","body":["The soft, responsive foam in the midsole gives you a comfortable, smooth ride for your run and wherever else your day takes you. The high foam heights provide a soft feel."]},{"header":"Fly Away","body":["The Flyknit upper has zones of breathability where your foot heats up most, specifically in the toe box. It''s strong and durable, helping keep your foot secure with every mile. The airy and breezy upper hugs your foot in a free and easy way."]}],"product_details":[{"header":"Product details","body":["Not intended for use as personal protective equipment (PPE)","Colour Shown: Sail/Platinum Tint/Summit White/Total Orange","Style: FD2291-103","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bc88815e-2835-49d1-8fe3-26a3e544896e/NIKE+INTERACT+RUN.png','960.11','2025-01-03 15:45:48.115959','2025-01-03 15:45:48.115959','running','men'),
	 ('4bb345e5-e91d-41d3-a6c9-846b0b1d6200','Nike Free RN NN','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole has at least 13% Nike Grind material, made from scraps from the footwear manufacturing process."]},{"header":"Lightweight Movement","body":["Flyknit gives you sock-like comfort with soft, stretchable and breathable fabric that helps keep you feeling light and airy when your run goes into overdrive. The inner sleeve is minimal but stretchy."]},{"header":"Soft in the middle","body":["An ultra-lightweight midsole offers incredible comfort as your foot repeatedly hits the road. It''s lighter, more responsive and softer than previous versions."]},{"header":"Stay Secure","body":["Embroidered eyestays around the laces help keep your feet secure. Pull tabs at the tongue and heel make for easy 1-hand entry."]},{"header":"Added flexibility","body":["Laser-cut grooves on the sole make this shoe more flexible."]}],"product_details":[{"header":"Product Details","body":["Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: Black/Anthracite/White","Style: FB1276-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/388d1fa1-5921-4181-9bf2-f37defd99521/NIKE+FREE+RN+FK+NEXT+NATURE.png','687.33','2025-01-03 15:45:48.116789','2025-01-03 15:45:48.116789','running','men'),
	 ('2cbe4717-a747-4516-a2fd-2415e55e738a','Nike Interact Run SE','{"benefits":[{"header":"To the future","body":["A scannable QR code on the tongue acts as your tour guide to the Interact Run''s performance benefits. It offers tips on how to extend the life cycle of your shoe from upkeep options to repairs and long-term care. Finally, when you''ve logged all the miles you can, the QR code will suggest ways to recycle and donate the shoes once they''ve run their course."]},{"header":"Made from Nike Grind","body":["The Waffle outsole is made from at least 13% Nike Grind material, crafted from scraps from the footwear-manufacturing process."]},{"header":"Soft ride","body":["The soft, responsive foam in the midsole gives you a comfortable, smooth ride for your run and wherever else your day takes you. The high foam heights provide a soft feel."]},{"header":"Fly away","body":["The Flyknit upper has zones of breathability where your foot heats up most, specifically in the toe box. It''s strong and durable, helping keep your foot secure with every mile. The airy and breezy upper hugs your feet in a free and easy way."]}],"product_details":[{"header":"Product details","body":["Weight: 260g (men''s size 9)","Heel-to-toe drop: 10mm","Colour Shown: Total Orange/Football Grey/Black/Volt","Style: HJ4294-800","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0096a56b-5421-4ff5-aff4-8499b15607e6/NIKE+INTERACT+RUN+SE.png','941.70','2025-01-03 15:45:48.118991','2025-01-03 15:45:48.118991','running','men'),
	 ('ffa0b60a-565a-4263-b440-dc6f051b326e','Nike Juniper Trail 2','{"benefits":[{"header":"Made from Nike Grind","body":["See the speckles on the outsole? That means it''s made with at least 8% Nike Grind material, made from scraps from the footwear manufacturing process."]},{"header":"Extra Stability","body":["The cables are integrated with the laces for a secure feel, while the inner sleeve wraps your midfoot for a sock-like fit."]},{"header":"Mixed Materials","body":["The upper blends mesh, synthetic leather and textile materials to give you both durability and breathability."]},{"header":"Tough Design","body":["A rubber outsole with tapered lugs helps you efficiently run uphill and downhill, while providing the traction you need on rocky roads. Thick material across the toe adds extra durability."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 318g (men''s size 9)","Heel-to-toe drop: 9.5mm","Foam midsole","Pull loops","Colour Shown: Medium Olive/Light Iron Ore/Lilac Bloom/Summit White","Style: DM0822-200","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bcbf014c-9187-465d-b7e8-3e9e3e252ccf/NIKE+JUNIPER+TRAIL+2+NN.png','877.80','2025-01-03 15:45:48.121217','2025-01-03 15:45:48.121217','running','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('911aabc2-32f6-4b34-8de9-373ab0d70522','Nike Downshifter 13','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole is made from at least 15% Nike Grind material, derived from scraps from the footwear-manufacturing process."]},{"header":"Breathable Mesh","body":["Soft and comfortable mesh offers a high level of breathability."]},{"header":"Supportive and secure","body":["An updated internal fit band offers containment around the midfoot for support and security."]}],"product_details":[{"header":"Product details","body":["Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Dark Smoke Grey/White","Style: FJ1284-001","Country/Region of Origin: Indonesia, Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bbadd922-52f3-4bbd-bfb2-8e9bca52c955/NIKE+DOWNSHIFTER+13+WIDE.png','444.37','2025-01-03 15:45:48.122941','2025-01-03 15:45:48.122941','running','men'),
	 ('bc51c086-8ffe-499d-bad7-b730c65ef0c2','Nike React Phantom Run Flyknit 2','{"benefits":[{"header":"Smooth and Responsive","body":["Nike React technology delivers an extremely smooth ride. It provides support for the 3 phases of a runner''s stride—flexibility at toe-off, a smooth ride at mid-stance and cushioning at contact."]},{"header":"Lightweight and Breathable","body":["Flyknit loft uses 3 forefoot layers. They combine for a lightweight, breathable and durable feel that keeps your foot comfortable."]},{"header":"Secure feel","body":["The latest in Flywire technology features an elastic design that intertwines with the Flyknit upper, helping your foot feel secure as you run."]}],"product_details":[{"header":"Product details","body":["Rubber on the outsole helps deliver better traction and durability.","Moulding around the heel keeps you feeling stable, so you can focus on your route.","Colour Shown: Sail/White/Light Bone/Black","Style: DV2139-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6b46ee80-6ebd-4935-8798-ff2665962bc0/NIKE+REACT+PHANTOM+RUN+FK+2.png','484.43','2025-01-03 15:45:48.124367','2025-01-03 15:45:48.124367','running','men'),
	 ('070e49e1-b4be-4b8f-b333-5bf1c111e7cb','Nike Zoom Superfly Elite 2','{"benefits":[{"header":"Lightweight, Ready to Race","body":["Introducing the latest version of Flyknit—AtomKnit.Flyknit fabric is stretched, steamed and set, delivering a lightweight, contoured fit with minimal water absorption and enhanced breathability."]},{"header":"Tough Grip","body":["The plate''s design was created using data from hundreds of runners.The result is an outsole with increased stiffness and reduced weight.Peaks throughout the plate provide traction, giving your foot grip as you run around turns.It includes 8 removable stainless-steel pins to grip the track."]}],"product_details":[{"header":"Product Details","body":["Ideal for 100m–400m sprinters","World Athletics approved","Colour Shown: Racer Blue/Lime Blast/Safety Orange/White","Style: CD4382-400","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ab537277-cbf7-4ce0-98cf-f104427dd2c5/NIKE+ZOOM+SUPERFLY+ELITE+2.png','747.65','2025-01-03 15:45:48.125059','2025-01-03 15:45:48.125059','running','men'),
	 ('e1fca1af-5955-418f-9989-6d9d418d3c0e','Ja 2 ''Purple Sky'' EP','{"benefits":[{"header":"Purple Sky","body":["Watching Ja soar above the court is the same as staring at a purple night sky. Astral graphics and lavish lavender give this special design a Ja-sized lift-off."]},{"header":"Zoom, zoom","body":["A forefoot Air Zoom unit helps provide increased responsiveness and vertical acceleration."]},{"header":"Lighter design","body":["We removed as much material in the arch as possible without sacrificing support, which helps reduce the overall weight of the shoe. The midsole is made to mould to your foot for better containment and support when making quick, sudden movements."]},{"header":"Tractor-inspired traction","body":["The multi-directional traction pattern pays homage to the oversized tractor tyres Ja still trains on in the Morant family''s back garden."]},{"header":"Light and breathable","body":["Lightweight mesh offers comfort and breathability in the upper while engineered mesh on the big-toe side of the shoe gives you even more breathability."]}],"product_details":[{"header":"Product details","body":["Not intended for use as personal protective equipment (PPE)","Colour Shown: Bold Berry/Light Lemon Twist/Dark Raisin/Baltic Blue","Style: FD7327-500","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/20fd0937-0c1e-4149-b098-607ce9c428be/JA+2+EP.png','449.45','2025-01-03 15:45:48.127285','2025-01-03 15:45:48.127285','basketball','women'),
	 ('b3a1c77c-602c-4e23-b320-f507bd2c417e','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Black/University Red/White","Style: FN4322-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e6cad6b9-b122-49d4-b15b-a504180b5a6c/NIKE+PRECISION+VII.png','540.49','2025-01-03 15:45:48.12817','2025-01-03 15:45:48.12817','basketball','women'),
