	 ('c08dd17e-445f-4db3-ab03-986cdf67dae1','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: White/Black","Style: FN4322-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0351925a-de56-4051-92bd-b4e88149e953/NIKE+PRECISION+VII.png','619.27','2025-01-03 15:45:48.13047','2025-01-03 15:45:48.13047','basketball','women'),
	 ('4f96c2dc-d07d-4d86-9d81-2e4dd309baa2','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Volt/Summit White/Barely Volt/Dark Smoke Grey","Style: FN4322-700","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/97fb8db1-8d01-451e-8dbf-5009b2cc2a79/NIKE+PRECISION+VII.png','949.06','2025-01-03 15:45:48.133062','2025-01-03 15:45:48.133062','basketball','women'),
	 ('3fd014e7-cdf8-4785-adae-15b19ece3191','LeBron XXII ''Tunnel Vision'' EP','{"benefits":[{"header":"Tunnel Vision","body":["Dark hues with bright accents create the look of a tunnel where LeBron locks in before taking the floor."]},{"header":"Support and speed","body":["The large forefoot Air Zoom unit is curved to bend in multiple directions. It provides energy return for fast and responsive cornering and offers a flexible court feel that moves naturally with your foot. A bottom-loaded Air Zoom unit in the heel adds cushioning and support."]},{"header":"Stay Steady","body":["A tough plastic plate in the midsole and sturdy, wing-shaped pieces on both sides of the shoe help keep you stable."]},{"header":"Soft and smooth","body":["The responsive foam in the midsole feels soft and smooth while keeping you low to the ground and enhancing the sensation of court feel."]}],"product_details":[{"header":"Product details","body":["The synthetic leather upper offers lightweight containment with optimal breathability","Multi-directional traction pattern","Colour Shown: Black/Dark Grey/Field Purple/Laser Fuchsia","Style: FZ1095-001","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/882393e6-9ff2-4e8e-a2ce-91875992971c/LEBRON+XXII+EP.png','624.90','2025-01-03 15:45:48.133806','2025-01-03 15:45:48.133806','basketball','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('cbd1ca1d-9c69-496b-a171-10ad4fd218f5','Nike Elevate 3','{"benefits":[{"header":"On-Point Pivots","body":["A generative, athlete-tested traction allows for better pivoting around the forefoot, allowing you to feel more secure and locked in when spinning, stopping and starting."]},{"header":"Lace Up","body":["We added extra lace holes on the medial midfoot to give you the extra security you need for all-important arch support."]}],"product_details":[{"header":"Product Details","body":["No-sew overlays","Foam midsole","Plush tongue","Colour Shown: White/Pure Platinum/Black","Style: DD9304-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5ba3b10c-b59c-4c7b-af60-71276ffe1f03/NIKE+RENEW+ELEVATE+III.png','647.54','2025-01-03 15:45:48.134487','2025-01-03 15:45:48.134487','basketball','women'),
	 ('d9e9a285-13e0-4d44-96ea-b4662073cccb','LeBron Witness 8 EP','{"benefits":[{"header":"Max Air made","body":["A Max Air unit in the low-profile midsole is combined with a foam wrap-up for support when you''re moving in lateral directions. It helps cushion your landing while supporting the smooth transition from heel to toe. It also provides side-to-side stability and helps harness and direct your force."]},{"header":"Secure feel","body":["Breathable mesh provides a lightweight, conforming fit in the upper, from the webbing that harnesses your forefoot to the external moulded pieces that help secure your heel. Reinforced stitching along the sides helps the shoe fit snugly for full-foot containment."]},{"header":"Stick and Move","body":["We split the rubber outsole and partially cut it out under the arch to help it bend and flex while helping reduce its overall weight. A classic herringbone pattern adds durable traction."]}],"product_details":[{"header":"Product details","body":["Padded collar","Diamond-stitched quilted tongue","Colour Shown: Light Crimson/Bright Crimson/Gym Red/White","Style: FB2237-600","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bf324a92-3ce0-47ac-be18-193f39f79095/LEBRON+WITNESS+VIII+EP.png','978.34','2025-01-03 15:45:48.135216','2025-01-03 15:45:48.135216','basketball','women'),
	 ('f8b965be-537a-41b5-b0bb-2a5a00c7fc0b','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Smoke Grey/Iron Grey/Hot Punch/Photon Dust","Style: FN4322-003","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/43aad5f0-7d09-49f6-999d-8f6dd61f4d6a/NIKE+PRECISION+VII.png','564.72','2025-01-03 15:45:48.136602','2025-01-03 15:45:48.136602','basketball','women'),
	 ('c55e7146-ed1b-4aa4-8e22-de66843bb856','Jordan Heir Series PF Showstopper''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in, do work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Pull tab on heel","Rubber outsole","Colour Shown: Sail/Vapour Green/Black","Style: FZ2473-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/67549078-1f37-4a8e-a27c-0ad5e1d89923/WMNS+JORDAN+HEIR+SERIES+PF.png','891.23','2025-01-03 15:45:48.137265','2025-01-03 15:45:48.137265','basketball','women'),
