	 ('0e1be47e-9774-44bc-b48c-6eec8c5b481d','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: White/Black","Style: FN4322-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0351925a-de56-4051-92bd-b4e88149e953/NIKE+PRECISION+VII.png','757.21','2025-01-03 15:45:48.138763','2025-01-03 15:45:48.138763','basketball','women'),
	 ('adab09d2-eb54-4701-b38a-fc2bf0a5d436','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Total Orange/Laser Orange/Photon Dust/Black","Style: FN4322-800","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3851856e-aa29-438d-9f49-048a7828663a/NIKE+PRECISION+VII.png','348.09','2025-01-03 15:45:48.139604','2025-01-03 15:45:48.139604','basketball','women'),
	 ('174b516f-c0b2-4a3d-bb66-0d05100eb211','Jordan Heir Series PF Showstopper''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in, do work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Pull tab on heel","Rubber outsole","Colour Shown: Sail/Vapour Green/Black","Style: FZ2473-100","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/67549078-1f37-4a8e-a27c-0ad5e1d89923/WMNS+JORDAN+HEIR+SERIES+PF.png','337.04','2025-01-03 15:45:48.141452','2025-01-03 15:45:48.141452','basketball','women'),
	 ('be6bc0dc-60f4-49d2-8071-6e81f4fc2489','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Football Grey/Pure Platinum/Plum Dust/Royal Pulse","Style: FN4322-004","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b5bea92b-2109-4c0f-86ad-7167cebd4477/NIKE+PRECISION+VII.png','730.21','2025-01-03 15:45:48.142121','2025-01-03 15:45:48.142121','basketball','women'),
	 ('f0a55b44-a386-4094-b293-76ce2a2a9d0e','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Black/Iron Grey/Smoke Grey/White","Style: FN4322-005","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/738aa0dc-403b-45fa-bbca-874a3b3e411d/NIKE+PRECISION+VII.png','481.35','2025-01-03 15:45:48.142882','2025-01-03 15:45:48.142882','basketball','women');
