	 ('b82db1b8-7919-434b-b0e9-b34b60ddbbfa','Jordan Heir Series PF ''Her Collective''','{"benefits":[{"header":"Contouring cage","body":["A built-in cage system contours to your foot to help give you the supportive fit you need when cutting across the court."]},{"header":"Drop in, do work","body":["A drop-in Cushlon 3.0 foam midsole puts lightweight and responsive cushioning directly underfoot, helping with on-court mobility. It''s also why the Heir is lower to the ground than any other performance basketball shoe in our collection."]},{"header":"Get a grip","body":["Rubber outsole with herringbone tread pattern helps give you the sticky traction you need to stop in an instant and shift directions."]}],"product_details":[{"header":"Product details","body":["The PF edition is designed with a wider fit and optimised for play on outdoor courts.","Pull tab on heel","Rubber outsole","Colour Shown: Black/Crimson Tint/Peach Cream/White","Style: FZ2473-018","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e1bb6e31-13e8-47e5-8ba5-5151a11e8ed4/WMNS+JORDAN+HEIR+SERIES+PF.png','481.37','2025-01-03 15:45:48.143607','2025-01-03 15:45:48.143607','basketball','women'),
	 ('aac9d823-a95a-41be-9328-b7c97a15d744','Nike Precision 7','{"benefits":[{"header":"All-game comfort","body":["The plush foam on the collar and tongue enhances the feeling of comfort around the ankle and over the top of the foot—areas where you want no distractions. It helps strike a sound balance between ground control when changing sudden direction and comfort when racing from one end of the floor to the other. The breathable mesh upper helps keep you contained."]},{"header":"Cushion for the push","body":["The sculpted foam midsole feels soft and supportive, providing cushioning for the game''s non-stop movement."]},{"header":"Stick and move","body":["Herringbone traction provides multi-directional grip, great for players who rely on their quickness and cutting ability. The rubber wraps up the sides in the forefoot to give you traction on your edges."]}],"product_details":[{"header":"Product details","body":["No-sew overlays","Moulded Swoosh logo","Colour Shown: Black/Iron Grey/Smoke Grey/White","Style: FN4322-005","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/738aa0dc-403b-45fa-bbca-874a3b3e411d/NIKE+PRECISION+VII.png','948.28','2025-01-03 15:45:48.144304','2025-01-03 15:45:48.144304','basketball','women'),
	 ('0062a69f-7fdc-42c6-9755-9d37546edec5','Nike Tiempo Legend 10 Club','{"benefits":[{"header":"Amplified touch","body":["The moulded synthetic leather mimics a quilted sensation for improved touch."]},{"header":"Natural, contouring fit","body":["The synthetic leather moulds to your foot and gives you better control, helping you stay comfortable for your match."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4344-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ec2b2eb3-a34f-4411-a6d9-fc218ef848ef/LEGEND+10+CLUB+FG%2FMG.png','577.84','2025-01-03 15:45:48.145979','2025-01-03 15:45:48.145979','football','women'),
	 ('8d24ce18-bea7-4c0b-bedc-9a726597d1e6','Nike Mercurial Superfly 10 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ1456-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/615bd8bf-ea41-487a-b3e1-70399eef6be6/ZM+SUPERFLY+10+ACAD+FG%2FMG.png','998.47','2025-01-03 15:45:48.146671','2025-01-03 15:45:48.146671','football','women'),
	 ('3842f30f-3357-4a6f-a10b-e0a79d194a3e','Nike Mercurial Vapor 16 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Dig in, take off","body":["Unique traction pattern offers super-charged traction with quick release to create separation."]},{"header":"Secure fit","body":["You get the same fit from the Vapor 15. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8441-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/05442d82-fde1-401f-a24e-33409f65c375/VAPOR+16+CLUB+FG%2FMG.png','557.96','2025-01-03 15:45:48.147331','2025-01-03 15:45:48.147331','football','women'),
	 ('99e27998-d6eb-4077-9a68-ea2180d57e94','Nike Mercurial Superfly 10 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Dig in, take off","body":["Unique traction pattern offers super-charged traction with quick release to create separation."]},{"header":"Secure fit","body":["You get the same fit from the Superfly 9. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8314-400","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/82182873-0ecc-4b73-898b-62c1d745e95e/SUPERFLY+10+CLUB+FG%2FMG.png','725.41','2025-01-03 15:45:48.148097','2025-01-03 15:45:48.148097','football','women'),
	 ('a1371c18-af74-43f3-adcf-97b5433c31e7','Nike React Gato','{"benefits":[{"header":"Nike Touch 360","body":["Flexible rubber pods underfoot reach just below the sole for improved touch and tactile responsiveness. Awareness of the ball is heightened as the pods extend up slightly under the cushioning into the sole of your foot."]},{"header":"Responsive Cushioning","body":["Full-length Nike React cushioning has incredible energy return to keep you moving."]},{"header":"Precise, Durable Touch","body":["Flyknit is fused with a durable compound and moulded to provide a precise touch at high-speeds. A reinforced band around the toe adds durability."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Cushioned insole","Colour Shown: Dusty Cactus/Barely Volt","Style: CT0550-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5a7c0696-a4b2-4ccc-ad29-e77fbb00294b/NIKE+REACTGATO.png','325.74','2025-01-03 15:45:48.148839','2025-01-03 15:45:48.148839','football','women'),
	 ('4f297ff1-4653-4159-9faf-781d9bed780d','Nike Phantom GX 2 Elite','{"benefits":[{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Sunset Pulse/Black","Style: FJ2559-600","Country/Region of Origin: Bosnia \u0026 Herzegovina"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2ff5f7f0-05f2-4c0a-9cbf-a466b834762b/PHANTOM+GX+II+ELITE+FG.png','855.58','2025-01-03 15:45:48.150986','2025-01-03 15:45:48.150986','football','women'),
	 ('230d7b04-9ac8-4d84-934d-e0d869d18f0b','Nike Mercurial Superfly 10 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["Rubber outsole provides traction on turf surfaces."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball. A Dynamic Fit collar wraps your ankle in soft, stretchy fabric for a secure feel."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Glacier Blue/Blue Orbit","Style: FQ8331-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a10e080b-1985-48dc-83d5-ce0d86a294b7/ZM+SUPERFLY+10+ACADEMY+TF.png','995.62','2025-01-03 15:45:48.151656','2025-01-03 15:45:48.151656','football','women'),
	 ('05e4ac79-8b57-4df5-a8f5-b1555eb995d4','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. The tongue construction with additional padding gives you a secure feel and comfort in key areas. Microfibre lining creates a premium feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Pink Foam/Black","Style: DV4337-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/75319ff1-e875-4391-9ccb-62517be3963d/LEGEND+10+ACADEMY+FG%2FMG.png','872.70','2025-01-03 15:45:48.153697','2025-01-03 15:45:48.153697','football','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('7f57d5af-3f36-440d-84ea-8378f26f0483','Nike Tiempo Legend 10 Elite','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4328-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a1a9a3a2-deac-4569-acd4-f3ae09b572df/LEGEND+10+ELITE+FG.png','390.55','2025-01-03 15:45:48.155247','2025-01-03 15:45:48.155247','football','women'),
	 ('af85ab8d-bba9-47b6-a005-2e42436427b1','Nike Phantom GX 2 Academy EasyOn Electric','{"benefits":[{"header":"FlyEase is now EasyOn","body":["As we continue to make more Nike products easier to wear and use for every body, we switched up the name to make it easier to understand. A shaped heel counter makes it easy put the boot on. A hook-and-loop strap with flexible webbing offers adjustability across the boot. Plus, braille on the heel helps you tell the difference between the left and right boots."]},{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The newly implemented blend of conical and tri-star studs help unlock change of direction and movement for an easy transition, allowing you to tack down into the grass for a quick take-off."]},{"header":"Comfortable fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned Insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FN8199-900","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/cb278f08-a4ad-43b8-824a-641196ddaf4c/PHANTOM+GX+II+ACAD+EASE+FGMG.png','631.20','2025-01-03 15:45:48.156828','2025-01-03 15:45:48.156828','football','women'),
	 ('4c216347-459c-408f-813b-d5ca5d27b33e','Nike Phantom GX 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the pinky toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Comfortable Fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FD6723-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c8d83936-f960-4d5f-be6f-9105c84a1fa0/PHANTOM+GX+II+ACADEMY+FG%2FMG.png','852.96','2025-01-03 15:45:48.157529','2025-01-03 15:45:48.157529','football','women'),
	 ('dbe85b51-ce21-4bcf-83e1-578b840e2af6','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Even better, they don''t sacrifice the ball control you crave on the turf. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. Tongue construction with additional padding gives you a secure feel and comfort in key strike zones. Microfibre lining creates a premium feel."]},{"header":"Traction for the Turf","body":["A rubber outsole gives you traction on turf surfaces."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: DV4342-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1c86329b-0136-4fb5-a7d3-cb1f0f7c5c7f/LEGEND+10+ACADEMY+TF.png','457.97','2025-01-03 15:45:48.158815','2025-01-03 15:45:48.158815','football','women'),
	 ('8ebfa31a-07b3-499d-ad58-95846c2652d9','Nike Phantom GX 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the shoe, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quick (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Comfortable Fit","body":["The soft upper helps keep you comfortable from kick-off to the final whistle."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FJ2577-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/62e3d9c1-0d94-4f95-b948-854d25549650/PHANTOM+GX+II+ACADEMY+TF.png','993.22','2025-01-03 15:45:48.162225','2025-01-03 15:45:48.162225','football','women'),
	 ('264e261e-1933-47a2-9f0b-cc5aa81e371e','Nike Mercurial Vapor 16 Club','{"benefits":[{"header":"Sticky touch","body":["A moulded, synthetic upper has a textured pattern for better ball control when dribbling at high speeds."]},{"header":"Reliable traction","body":["Rubber outsole is designed for traction on turf surfaces."]},{"header":"Secure fit","body":["You get the same fit from the Vapor 15. This means a design that better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ8446-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/330b8b63-9bb6-4399-9c7c-1d68bfdcfdd3/VAPOR+16+CLUB+TF.png','993.75','2025-01-03 15:45:48.163059','2025-01-03 15:45:48.163059','football','women'),
	 ('50d74559-7cd1-4bd9-a7a8-7d6efddeac5e','Nike Mercurial Vapor 16 Academy','{"benefits":[{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["A rubber outsole gives you traction for turf surfaces."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ8449-002","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/93ca7a3c-9f8c-4278-bb3e-97fd11e3dd40/ZOOM+VAPOR+16+ACADEMY+TF.png','945.64','2025-01-03 15:45:48.163904','2025-01-03 15:45:48.163904','football','women'),
	 ('c6de027d-77bc-4d58-9c97-89e56c45bb31','Nike Tiempo Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Even better, they don''t sacrifice the ball control you crave on the court. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. The tongue construction with additional padding gives you a secure feel and comfort in key areas. Microfibre lining creates a premium feel."]},{"header":"Traction for the court","body":["The rubber outsole gives you traction for street, court and indoor surfaces."]}],"product_details":[{"header":"Product details","body":["For use on street, court and indoor surfaces","Cushioned insole","Colour Shown: Pink Foam/Port Wine","Style: DV4341-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/d135c2e6-fd7c-473d-8b2c-b45f31af088d/LEGEND+10+ACADEMY+IC.png','491.13','2025-01-03 15:45:48.17238','2025-01-03 15:45:48.17238','football','women'),
	 ('7da19ad6-6afb-4eed-8e6d-1341645ccb80','Nike Tiempo Legend 10 Elite Electric','{"benefits":[{"header":"Exceptional touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the boot. All Conditions Control (ACC) technology adds a grippy texture in both wet and dry conditions."]},{"header":"Natural, contouring fit","body":["The FlyTouch Plus engineered leather is incredibly soft. It helps the boot mould to your foot for comfort without overstretching the material. Flyknit around the ankle gives you a secure feel."]},{"header":"Traction for the pitch","body":["The plate places conical studs in the heel for optimal traction and stability when braking and changing direction—just right under any conditions."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Multi-Colour/Multi-Colour","Style: FQ3249-900","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c291f5b4-2622-4470-897e-0ecf77618bc6/LEGEND+10+ELITE+FG+OLY.png','810.48','2025-01-03 15:45:48.167808','2025-01-03 15:45:48.167808','football','women'),
	 ('21dbfc6f-f58d-4238-a435-3f8dde6d768c','Nike Mercurial Vapor 16 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: Black/Deep Jungle/Black","Style: FQ1457-002","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/54449b69-7cc3-4459-b772-276fa932b9ee/ZM+VAPOR+16+ELITE+FG.png','906.29','2025-01-03 15:45:48.168661','2025-01-03 15:45:48.168661','football','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('3b086486-d10f-417e-85bd-c44525aa1f59','Nike Phantom GX 2 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides exceptional touch to the ball. It covers the striking area of the boot, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks. It moulds to the shape of your foot and gives you great grip in wet or dry conditions. Micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Quick traction","body":["The Nike Cyclone 360 traction pattern helps you make quicker (improved agility when making cuts) and confident (helps reduce rotational traction) movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up."]},{"header":"Snug fit","body":["Asymmetric lacing offers a large touch surface when dribbling, passing and scoring. A repositioned lacing pattern allows for increased midfoot adjustability to accommodate players with flatter or higher arches. Flyknit material provides snugness and shape to help bring comfort around the collar."]}],"product_details":[{"header":"Product details","body":["For use on longer, artificial-grass surfaces","Cushioned insole","Colour Shown: Metallic Silver/Volt/Black","Style: FJ2554-003","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ee409eb2-398a-42f5-9698-826b5c936aa2/PHANTOM+GX+II+ELITE+AG-PRO.png','676.23','2025-01-03 15:45:48.169352','2025-01-03 15:45:48.169352','football','women'),
	 ('d88cb2ba-7320-4573-be73-0c31ab860f78','Nike Phantom Luna 2 Academy','{"benefits":[{"header":"Amplified touch","body":["We''ve expanded the NikeSkin touch zone from the previous version. This brings your foot even closer to the ball for better control while dribbling and passing in wet or dry conditions. It covers the striking area of the shoe, stretching from the big-toe side all the way across the laces to the little toe, allowing clean boot-to-ball kicks."]},{"header":"Quick traction","body":["An integrated traction pattern helps you make quick and confident movements, so you can cut with speed while feeling fully secure when the game''s intensity turns up on the turf."]},{"header":"Fit for the pitch","body":["The cuff offers soft comfort around your ankle and heel. Subtle ribs in the cuff allow for ball contact higher up the ankle in trapping and passing."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Blue Fury/White","Style: FJ2566-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c1436f2d-e3a5-43f0-9788-bd48ea53facf/PHANTOM+LUNA+II+ACADEMY+TF.png','382.51','2025-01-03 15:45:48.170889','2025-01-03 15:45:48.170889','football','women'),
	 ('c7ea3a1e-2c73-4fff-8e6d-66f8e5b3c7c4','Jordan Hex','{"benefits":[{"header":"Distinct Lines","body":["With a squared-off toe and sleek design, these aren''t your grandma''s slides."]},{"header":"Slip-In Comfort","body":["The fixed strap keeps you contained (and makes a statement, with a mix of matt and shiny finishes)."]},{"header":"Soft and Durable","body":["Foam is soft and pliable for comfort, yet durable for long-lasting wear. It''s moulded with traction inspired by the AJ1."]}],"product_details":[{"header":"Product Details","body":["Deep heel cup is moulded for a stable, comfortable fit.","Raised toe bar helps provide grip as you walk.","\"Jordan\" is debossed in the heel.","Colour Shown: Legend Pink/Legend Pink","Style: DQ8992-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/dcbcb8f7-c35b-412a-aef7-377e334163df/WMNS+JORDAN+HEX+SLIDE.png','649.28','2025-01-03 15:45:48.18709','2025-01-03 15:45:48.18709','lifestyle','women'),
	 ('f696a0ba-597c-45e1-bece-08848ed379d9','Nike Phoenix Waffle','{"benefits":[{"header":"Rooted in heritage","body":["The reflective design windows are inspired by Blue Ribbon Sports and vintage running shoes."]},{"header":"Cushiony goodness","body":["The increased midsole height enhances stability and underfoot cushioning for a smooth, comfortable ride."]},{"header":"Tread lightly","body":["The redesigned Waffle tread is better than ever with evolved lug placements and outsole weight reduction."]}],"product_details":[{"header":"Product details","body":["Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Summit White/Sand Drift/Sail/Black","Style: FD2196-100","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6474a74c-471d-42eb-9771-03a34ec5cd9a/W+NIKE+PHOENIX+WAFFLE.png','498.57','2025-01-03 15:45:48.2024','2025-01-03 15:45:48.2024','lifestyle','women'),
	 ('141d6599-f533-49a5-8ccb-b05df0309e9e','Nike Tiempo Emerald Legend 10 Academy','{"benefits":[{"header":"Amplified touch","body":["See those micro-dots on the upper? They amplify touch zones for shooting, dribbling and passing. They make for a sleeker look while taking out the extra padding. Better still, they don''t sacrifice the ball control you crave on the pitch. We shaved down the foam pods from the Tiempo 9, so your foot can get even closer to the ball when it''s in your control. Instead, we moulded the lines into the shoe."]},{"header":"Natural, contouring fit","body":["The FlyTouch Lite engineered leather is incredibly soft. It helps the shoe mould to your foot for comfort without overstretching the material. The tongue construction with additional padding gives you a secure feel and comfort in key areas. Microfibre lining creates a premium feel."]},{"header":"Traction for the Turf","body":["A rubber outsole gives you traction on turf surfaces."]}],"product_details":[{"header":"Product details","body":["For use on shorter, synthetic surfaces","Cushioned insole","Colour Shown: Dark Atomic Teal/Sail","Style: FQ3245-300","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ab88b180-988e-4701-ae7c-8cdee123e7a6/LEGEND+10+ACADEMY+TF+30.png','685.86','2025-01-03 15:45:48.173337','2025-01-03 15:45:48.173337','football','women'),
	 ('e091af09-5f81-4b15-aa27-044d18404be1','Nike Vapor 16 Academy Mercurial Dream Speed','{"benefits":[{"header":"Believe in yourself","body":["The distorted pattern along the forefoot speaks to the big breakthrough moment, when confidence carries you further than you thought possible. The calmer, smoother tones along the heel represent being present in the moment. Blue encourages better mind flow and performance. Orange promotes focus, concentration and creativity. The metallic chromes nod to goals and successes."]},{"header":"Amplified touch","body":["The upper is made from NikeSkin with embedded chevrons, which helps provide ball control and truly gives you a feeling of barefoot football."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved chevron and blade studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["We''ve upgraded the stretch mesh from the previous generation to an adaptable knit that offers flexibility, provides support and brings you closer to the ball."]}],"product_details":[{"header":"Product details","body":["For use on natural and synthetic surfaces","Cushioned insole","Colour Shown: Barely Green/Crimson Pulse/Metallic Gold Coin","Style: FZ1388-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/01ef5c55-1991-46f5-b261-7812c92b432a/ZM+VAPOR+16+ACADEMY+MDS+FG%2FMG.png','961.94','2025-01-03 15:45:48.176629','2025-01-03 15:45:48.176629','football','women'),
	 ('81a23624-b598-4c2f-a351-b8a45f99e9eb','Nike Zoom Mercurial Superfly 9 Elite ''Marcus Rashford''','{"benefits":[{"header":"\"When you believe in yourself … \"","body":["\"Incredible things can happen.\" Check out the insole for an inspirational quote from Marcus. The graphics represent amplified sound waves, a nod to Marcus'' desire to lift up others, while the colours celebrate various debut boots he''s worn."]},{"header":"Springy underfoot feel","body":["The 3/4-length Zoom Air unit sits in the outsole and provides an additional level of springy underfoot cushioning that helps you move faster on the pitch. It creates separation when it matters the most—whether you''re scoring goals, being first to the ball or going by defenders."]},{"header":"Drive your speed","body":["The speed cage inside the structure is made from a thin but strong material that secures the foot to the outsole without adding additional weight for optimal stability."]},{"header":"Dig in, take off","body":["Tri-star studs provide multi-directional traction with every step, so you can change directions quickly and confidently. Heel studs provide traction and stability when braking. Toe-off centre studs give you traction during explosive starts."]},{"header":"Improved fit","body":["Flyknit wraps your ankle in soft, stretchy fabric for a secure feel. A redone design improves the fit, so that it better simulates the foot. We did this by conducting multiple wear tests on hundreds of athletes. The result is a more contoured toe box and secure feel in the heel."]},{"header":"Feel the ball","body":["The upper is made from Vaporposite+, which combines a grippy, grid mesh with a premium material for optimal ball control at high speeds. The material provides a tactile feel across the surface of the upper. It''s soft but stable, and wraps tightly around your foot, giving you a more natural on-ball feel when dribbling, passing or scoring."]}],"product_details":[{"header":"Product details","body":["For use on slightly wet, short-grass pitches","Cushioned insole","Colour Shown: White/Black","Style: FD1171-100","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8e644f9b-4db8-4d24-91d3-1edf45ae1e3c/ZOOM+SUPERFLY+9+ELITE+MR+FG.png','358.07','2025-01-03 15:45:48.177457','2025-01-03 15:45:48.177457','football','women'),
	 ('c32a703b-e068-4187-908e-043bf7038484','Nike Air Force 1 Shadow','{"benefits":[{"header":"Layered Look","body":["With 2 eyestays, 2 mudguards, 2 back tabs and 2 Swoosh designs, you get a layered look with double the branding."]},{"header":"Lightweight Comfort","body":["A foam midsole and a grooved outsole ensure that the shoe is lightweight, flexible and comfortable."]},{"header":"Iconic Shape","body":["Featuring the same iconic shape as the original Air Force 1, a slightly exaggerated midsole makes the shoe instantly recognisable while also playing with proportions."]}],"product_details":[{"header":"Product Details","body":["Midsole height: 41mm","Mix of leather and synthetic materials","Rubber tape","Colour Shown: White/White/White","Style: CI0919-100","Country/Region of Origin: China, Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/l3w4varugbogihcpj40e/W+AF1+SHADOW.png','595.17','2025-01-03 15:45:48.178319','2025-01-03 15:45:48.178319','lifestyle','women'),
	 ('b2d2eb99-2d0f-452e-ae40-9b9007e4a98e','Nike Mercurial Vapor 16 Elite','{"benefits":[{"header":"Exceptional touch","body":["Nike Gripknit is a sticky material that provides better touch to the ball. It takes up more surface area, so you have more room to control the ball when dribbling at high speeds or finish a play with a shot on goal. It moulds to the shape of your foot and gives you equal grip in wet or dry conditions for a sculpted, track spike-like fit. The micro-moulding texture works with Gripknit to help form to your foot for even better boot-to-ball strikes."]},{"header":"Fast traction","body":["The wave-like traction pattern is a series of cascading studs, so it engages more surface area of the Air Zoom unit while also providing the appropriate amount of grip. The biggest stud is the same height as our traditional middle studs, so traction is not compromised. We paired the wave-like traction with evolved studs to help you stop when making quick cuts."]},{"header":"Snug fit","body":["The full Flyknit upper is engineered for speed. AtomKnit, an incredibly lightweight and strong Flyknit, on the sides tapers weight and provides support. The Gripknit, AtomKnit and Flyknit combine to form the thinnest Mercurial upper to date, bringing you closer to the ball and lessening break-in time."]}],"product_details":[{"header":"Product details","body":["For use on longer, artificial-grass surfaces","Cushioned insole","Colour Shown: Volt/Black","Style: FQ8693-700","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/46957b3d-a518-4cb1-9ce1-b6d14e7c3016/ZM+VAPOR+16+ELITE+AG-PRO.png','569.69','2025-01-03 15:45:48.182018','2025-01-03 15:45:48.182018','football','women'),
	 ('b7f44758-a6a5-4d27-80cf-f220eb9fcf18','Jordan Hex','{"benefits":[{"header":"Distinct Lines","body":["With a squared-off toe and sleek design, these aren''t your grandma''s slides."]},{"header":"Slip-In Comfort","body":["The fixed strap keeps you contained (and makes a statement, with a mix of matt and shiny finishes)."]},{"header":"Soft and Durable","body":["Foam is soft and pliable for comfort, yet durable for long-lasting wear. It''s moulded with traction inspired by the AJ1."]}],"product_details":[{"header":"Product Details","body":["Deep heel cup is moulded for a stable, comfortable fit.","Raised toe bar helps provide grip as you walk.","\"Jordan\" is debossed in the heel.","Colour Shown: Legend Pink/Legend Pink","Style: DQ8992-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/dcbcb8f7-c35b-412a-aef7-377e334163df/WMNS+JORDAN+HEX+SLIDE.png','672.39','2025-01-03 15:45:48.184971','2025-01-03 15:45:48.184971','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('c64f2ec5-a4d4-4c53-9108-50a90ac5e93f','Nike Air Force 1 Sage Low','{"benefits":[{"header":"Clean Look","body":["Luxe upper features premium leather for a clean, sophisticated look.Stitch-and-turn construction creates a streamlined, easy-to-style look."]},{"header":"A Classic Re-Imagined","body":["The classic Air Force 1 foam midsole is exaggerated, creating a platform look.Enlarged outsole teeth add a modern take on the AF-1 design."]},{"header":"Breathable Comfort","body":["The original AF-1 perforation pattern creates an airy aesthetic that lets your foot breathe."]}],"product_details":[{"header":"Product Details","body":["Platform midsole","Leather, synthetic or textile upper (depending on colour)","Foam sole includes Air cushioning","Non-marking rubber outsole for traction and durability","Colour Shown: College Grey/Pale Ivory/College Grey","Style: AR5339-004","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bce70efe-62eb-4846-b895-fddb2474190a/W+AF1+SAGE+LOW.png','662.94','2025-01-03 15:45:48.185728','2025-01-03 15:45:48.185728','lifestyle','women'),
	 ('4fc44370-bcdd-4ece-959f-38c222989f94','Nike Air Max Furyosa NRG','{"benefits":[{"header":"Be bold, be comfortable","body":["Stacked, visible and offset: the Nike Air cushioning in the heel delivers a new look that adds comfort to your journey."]},{"header":"Wear what you demand","body":["Higher arch support, a wider forefoot and a lowered ankle scoop—it''s specifically designed for the unique shape of a woman''s foot and delivers the perfect fit straight out of the box."]},{"header":"Be spontaneous","body":["The dual-lacing system lets you be as expressive as you want. Wrap it, lace it, bow it or remove it to fit your style."]},{"header":"Step into luxury","body":["The layered design builds a shoe within a shoe, giving you the luxury feel of a slipper. The heel pillow, ultra-plush tongue and padded collar feel great while maintaining a modern look."]}],"product_details":[{"header":"Product details","body":["Pull tabs","''90s-style branding","Not intended for use as personal protective equipment (PPE)","Colour Shown: Sail/Phantom/Platinum Violet/Black","Style: DC7350-101","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/64d46d2b-be66-45b3-99e6-d4c5f627ec98/W+AIR+MAX+FURYOSA+NRG.png','862.14','2025-01-03 15:45:48.18639','2025-01-03 15:45:48.18639','lifestyle','women'),
