	 ('ea018f44-7857-4cb8-ae1d-b69203798863','Nike Downshifter 13','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole is made from at least 15% Nike Grind material, derived from scraps from the footwear-manufacturing process."]},{"header":"Breathable Mesh","body":["Soft and comfortable mesh offers a high level of breathability."]},{"header":"Supportive and secure","body":["An updated internal fit band offers containment around the midfoot for support and security."]}],"product_details":[{"header":"Product details","body":["Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Dark Smoke Grey/White","Style: FD6476-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/190a0fe3-46dc-4d5e-a6f4-4588bfb9756f/W+NIKE+DOWNSHIFTER+13.png','859.07','2025-01-03 15:45:48.208616','2025-01-03 15:45:48.208616','running','women'),
	 ('a8054288-70eb-444e-a7de-090f5bdf1754','Nike Downshifter 13','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole is made from at least 15% Nike Grind material, derived from scraps from the footwear-manufacturing process."]},{"header":"Breathable Mesh","body":["Soft and comfortable mesh offers a high level of breathability."]},{"header":"Supportive and secure","body":["An updated internal fit band offers containment around the midfoot for support and security."]}],"product_details":[{"header":"Product details","body":["Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Astronomy Blue/Beyond Pink/White/Black","Style: FD6476-400","Country/Region of Origin: Indonesia"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/12c8b926-e037-4c49-b09f-567eb4798f5e/W+NIKE+DOWNSHIFTER+13.png','743.60','2025-01-03 15:45:48.209329','2025-01-03 15:45:48.209329','running','women'),
	 ('17104573-51a3-4ee6-8df3-4acb433f9fcf','Nike Juniper Trail 3','{"benefits":[{"header":"All-terrain ready","body":["The Nike Trail ATC outsole is made from an all-terrain compound that''s great even in wet weather. It provides grip on any surface while maintaining durability and a smooth ride on the road."]},{"header":"Smooth Ride","body":["The full-length foam midsole provides a soft and cushioned ride. A flexible midfoot system connects the upper and midsole for increased support and stability."]},{"header":"Soft touch","body":["We''ve softened the touch points along the collar foam and tongue to help minimise distractions."]},{"header":"Comfort and Containment","body":["Durable mesh provides comfort and containment."]}],"product_details":[{"header":"Product details","body":["Weight: 272g approx. (women''s size 5.5)","Heel-to-toe drop: 10mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Wolf Grey/Photon Dust/Black","Style: FQ0902-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bfe41be6-2070-4e3b-9865-0e9d40b77166/W+NIKE+JUNIPER+TRAIL+3.png','951.18','2025-01-03 15:45:48.210736','2025-01-03 15:45:48.210736','running','women'),
	 ('0cb459bb-cfa8-497c-86e0-b73aad2094f1','Nike Alphafly 3 Electric','{"benefits":[{"header":"Energy return for your marathon","body":["Two forefoot Air Zoom units combine with ZoomX foam to store and return the energy back to you, powering every step."]},{"header":"Propulsive feeling","body":["A full-length carbon-fibre plate delivers a propulsive sensation that helps you smoothly transition through every stride and tackle turns with confidence."]},{"header":"Cushioned ride","body":["Fully connected ZoomX foam creates an ultralight and cushioned feel, helping you stay fresh and comfortable from mile 1 to 26.2."]},{"header":"What''s new about the Alphafly 3?","body":["The Alphafly 3 is our lightest Alphafly ever, featuring a slightly wider carbon-fibre plate for increased stability, a fully connected ZoomX foam midsole for smoother transitions and an all-new AtomKnit upper designed for improved multi-directional containment and breathability."]}],"product_details":[{"header":"Product details","body":["Weight: 174g approx. (women''s UK 5.5)","Heel-to-toe drop: 8mm","Colour Shown: Multi-Colour/Multi-Colour","Style: FN7673-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/69a80e20-7319-4263-a8ab-20440ea94f4a/W+AIR+ZM+ALPHAFLY+NEXT%25+3+OLY.png','662.43','2025-01-03 15:45:48.212367','2025-01-03 15:45:48.212367','running','women'),
	 ('e7f31fc7-9fc9-4538-83be-d8f0f4c1c864','Nike Zegama 2','{"benefits":[{"header":"Stay sticky","body":["Vibram Zegama outsole made with Vibram Megagrip has a diverse lug pattern highlighted with wide spacing. This means you get traction for more technical terrains."]},{"header":"Keep running","body":["A lightweight Nike ZoomX midsole is combined with increased stack heights to help provide cushioning during extended stretches of running."]},{"header":"Stable for trails","body":["Engineered mesh—stronger and more flexible than normal mesh—on the upper helps provide stability for various trail conditions."]}],"product_details":[{"header":"Product details","body":["Weight: 264g approx. (Women''s UK 5.5)","Heel-to-toe drop: 4mm","Reflective design details","Not intended for use as personal protective equipment (PPE)","Colour Shown: Jade Horizon/Cyber/Crimson Tint/Sail","Style: FD5191-300","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3232102b-23d9-4857-a095-7a9e3d3dc507/W+NIKE+ZOOMX+ZEGAMA+TRAIL+2.png','678.35','2025-01-03 15:45:48.213041','2025-01-03 15:45:48.213041','running','women'),
	 ('e9259699-13ed-4771-a98d-6c5ab3635448','Nike InfinityRN 4','{"benefits":[{"header":"Responsiveness: moderate","body":["The more responsive the shoe, the more energy return you can get back with each step. Whether you want to run a little bit faster or with a little less effort, responsive shoes help give you slightly more spring in your step to get more out of your run. ReactX foam gives you +13% energy return compared with React foam, helping you stay fresh and bouncy during your run."]},{"header":"Contained breathability","body":["A water-repellent liner in the toe helps keep you dry when the weather turns."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 281g (women''s size 5.5)","Heel-to-toe drop: 9mm","Not intended for use as personal protective equipment (PPE)","Colour Shown: Black/Dark Grey/White","Style: FN0880-001","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/056c3a04-b6bb-4523-b274-f2683e9d40f2/W+NIKE+REACTX+INFINITY+RUN+4+W.png','613.99','2025-01-03 15:45:48.213697','2025-01-03 15:45:48.213697','running','women'),
	 ('04c772b1-79fc-43aa-8690-3bc3583c28f8','Nike Vaporfly 3 Electric','{"benefits":[{"header":"Propelling you forwards","body":["A full-length carbon-fibre Flyplate provides a stiff and propulsive feel."]},{"header":"Speed for miles","body":["Nike ZoomX, our most responsive foam, just got a little better. Running from heel to toe, it unlocks even more energy return than before, giving you a springy, bouncy feel."]},{"header":"Stable ride","body":["See how the midsole bulges out by the heel? We designed it that way to help reduce weight on the inside of the foot to give you a more stable ride."]},{"header":"Feel the breeze","body":["Specifically selected Flyknit yarns and engineered zones in the forefoot bring a new level of performance to the Vaporfly. Ample breathability around the toes combined with soft, yet supportive yarns deliver our most customised upper for the Vaporfly. The result is a softer, cooler design that contours to your foot."]},{"header":"What''s new about the Vaporfly 3?","body":["An updated thin outsole rubber uses less material without sacrificing durability, which helps reduce outsole weight and thickness. This allows for extra millimetres of ZoomX foam underfoot and a smoother transition through your stride."]}],"product_details":[{"header":"Product details","body":["Weight: approx. 165g (women''s UK 5.5)","Heel-to-toe drop: 8mm","Wider toe area for a roomier fit","Internal foam pod on the heel for extra cushioning","Colour Shown: Multi-Colour/Multi-Colour","Style: FN7674-900","Country/Region of Origin: China"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/467c9f92-2ced-40d1-b663-06b9089c1436/W+ZOOMX+VAPORFLY+NEXT%25+3+OLY.png','661.89','2025-01-03 15:45:48.215144','2025-01-03 15:45:48.215144','running','women'),
	 ('b8a8dd55-6822-4061-84dd-bdf15950353e','Nike React Phantom Run Flyknit 2','{"benefits":[{"header":"Smooth and Responsive","body":["Nike React technology delivers a soft, smooth, responsive ride. The shape of the foam midsole is all about zonal performance. It provides support for the 3 phases of a runner''s stride—flexibility at toe-off, a smooth ride at mid-stance and cushioning at contact."]},{"header":"Secure Feel","body":["The latest in Flywire technology features an elastic design that intertwines with the Flyknit upper, helping your foot feel secure as you run."]},{"header":"Lightweight and Breathable","body":["Flyknit Loft is the latest update to the popular material. 3 forefoot layers are combined for a lightweight, breathable and durable feel that keeps your foot comfortable."]}],"product_details":[{"header":"Product Details","body":["Increased rubber on the outsole helps deliver traction and durability.","Moulding around the heel keeps you secure so you can focus on your route.","Offset: 10mm (Forefoot: 18.5mm, Heel: 28.5mm)","Colour Shown: Black/White","Style: CJ0280-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bb64be96-55d8-4fe2-93d9-f83c4fb2d3e3/W+NIKE+REACT+PHANTOM+RUN+FK+2.png','663.69','2025-01-03 15:45:48.222593','2025-01-03 15:45:48.222593','running','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('5014d737-b86f-4f77-b54f-fd58f6343575','Nike Streakfly','{"benefits":[{"header":"Low and nimble","body":["A full-length ZoomX midsole provides optimal lightweight responsiveness. The foam stack heights are lower than the Vaporfly, saving weight and giving you a more aggressive feel. It results in a shoe so light it disappears on your foot, while still giving you the responsive cushioning of ZoomX foam, helping you reach your fastest pace throughout the turns and accelerations of any race."]},{"header":"Supportive and sleek","body":["An ultra-thin knit upper is light in weight while still providing the support you need for racing. Extra reinforcement in the forefoot helps keep you secure. The updated, sleek lacing system is laterally offset with a notched tongue to help relieve pressure on the top of the foot."]},{"header":"Grip where it counts","body":["Runner-informed data was used to create the outsole. It uses that information to place traction where you need it the most, with a pattern that connects to the pavement based on how your foot hits the ground. The result is solid grip from foot contact to toe-off, helping you stay ahead of the competition."]}],"product_details":[{"header":"Product details","body":["Weight: Approx. 185g (men''s size 9)","Heel-to-toe drop: 6mm","Colour Shown: Volt/Bright Crimson/Volt/Black","Style: DJ6566-700","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1bf6f4d9-0b4d-4477-9406-9f6c01250096/NIKE+ZOOMX+STREAKFLY.png','867.84','2025-01-03 15:45:48.215919','2025-01-03 15:45:48.215919','running','women'),
	 ('4a46b134-672c-43d2-ab0a-132164952894','Nike Run Swift 3','{"benefits":[{"header":"Cushion with Every Step","body":["Foam cushioning delivers a soft underfoot feel. A higher foam height gives you a plush sensation with every step."]},{"header":"Secure Fit","body":["Flywire cables help secure your feet and provide support when you tighten the laces, so you can stay stable."]}],"product_details":[{"header":"Product Details","body":["Heel overlay for added security","Mesh by the toe for breathability","Flex grooves on rugged rubber outsole for flexibility","Colour Shown: Washed Coral/Magic Ember/Racer Blue/Anthracite","Style: DR2698-601","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c0823c45-1b85-48a9-9386-1fb29a6a25d3/W+NIKE+RUN+SWIFT+3.png','745.41','2025-01-03 15:45:48.216829','2025-01-03 15:45:48.216829','running','women'),
