	 ('f3794f6d-4f2d-4cfb-8734-e7aae6cba3e3','Nike Run Swift 3','{"benefits":[{"header":"Cushion with Every Step","body":["Foam cushioning delivers a soft underfoot feel. A higher foam height gives you a plush sensation with every step."]},{"header":"Secure Fit","body":["Flywire cables help secure your feet and provide support when you tighten the laces, so you can stay stable."]}],"product_details":[{"header":"Product Details","body":["Heel overlay for added security","Mesh by the toe for breathability","Flex grooves on rugged rubber outsole for flexibility","Colour Shown: Black/Dark Smoke Grey/White","Style: DR2698-002","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/09b261ec-1087-4e25-aed8-57274f1df309/W+NIKE+RUN+SWIFT+3.png','665.85','2025-01-03 15:45:48.218275','2025-01-03 15:45:48.218275','running','women'),
