	 ('f1395c95-03e8-40e2-af7e-50eaaead29be','Nike Free RN NN','{"benefits":[{"header":"Made from Nike Grind","body":["The outsole has at least 13% Nike Grind material, made from scraps from the footwear manufacturing process.﻿"]},{"header":"Lightweight movement","body":["Flyknit gives you sock-like comfort with soft, stretchable and breathable fabric that helps keep you feeling light and airy when your run goes into overdrive. Inner sleeve is minimal but stretchy."]},{"header":"Soft in the middle","body":["An ultra-lightweight midsole offers unreal comfort as your foot repeatedly hits the road. It''s lighter, more responsive and softer than previous versions."]},{"header":"Stay secure","body":["Embroidered eyestays around the laces help keep your feet secure. Pull tabs at the tongue and heel make for an easy one-hand entry."]},{"header":"Added flexibility","body":["Laser-cut grooves on the sole make this shoe more flexible."]}],"product_details":[{"header":"Product details","body":["Not intended for use as Personal Protective Equipment (PPE)","Colour Shown: Lilac Bloom/Barely Grape/Vivid Purple/Black","Style: DX6482-500","Country/Region of Origin: Vietnam"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2bf6fcd2-6fd0-4cae-b956-3225789a35e1/W+NIKE+FREE+RN+FK+NEXT+NATURE.png','652.06','2025-01-03 15:45:48.182767','2025-01-03 15:45:48.182767','running','men'),
	 ('e4f8ca1d-4df9-44ae-95c8-d011f0c3e4ea','Nike Bella 6 Premium','{"benefits":[{"header":"Vroom, vroom, Zoom","body":["An Air Zoom unit stretches from the heel to the midfoot, adding comfort to every step."]},{"header":"Revamped frame","body":["An updated frame in the forefoot creates more volume for an inclusive fit, while maintaining a confident shape and stance."]},{"header":"Stay solid","body":["Midfoot lacing enhances support without completely locking your foot into place. The flat sole helps keep you stable on gym surfaces."]},{"header":"Cool and Comfortable","body":["An inner sleeve improves ease of entry into the design while maintaining upper support. An ultra-cushiony collar helps keep your ankle and heel comfortable and extends to the tongue."]}],"product_details":[{"header":"Product details","body":["Foam midsole","Heel pull tab","Colour Shown: Summit White/Black/Sail/Metallic Silver","Style: FZ1714-100","Country/Region of Origin: India"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/84e02b77-65bf-41aa-aa6e-3025cb55de26/W+NIKE+ZOOM+BELLA+6+PRM.png','481.16','2025-01-03 15:45:48.180188','2025-01-03 15:45:48.180188','gym','women');
